INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MiguelElGallo/snowflake-semantic-view-skill/snowflake-semantic-views', 'snowflake-semantic-views', 'MiguelElGallo', 'snowflake-semantic-view-skill', 'community', 'snowflake-semantic-views MiguelElGallo snowflake-semantic-view-skill community snowflake-semantic-views是一种用于创建和增强Snowflake语义视图的AI工具，帮助开发者简化SQL数据分析 snowflake-semantic-viewsは、Snowflakeセマンティックビューの作成と強化を支援するAIエージェントです。開発者はSQLデータ分析を簡素化できます snowflake-semantic-views는 Snowflake 의미 뷰를 생성 및 강화하는 AI 에이전트로 개발자가 SQL 데이터 분석을 단순화하는 데 도움을 줍니다 La habilidad de Snowflake para crear y mejorar vistas semánticas en SQL mediante inteligencia artificial La compétence Snowflake pour créer et améliorer des vues sémantiques en SQL via l''intelligence artificielle Die Fähigkeit von Snowflake, semantische Ansichten in SQL durch KI zu erstellen und zu verbessern A habilidade snowflake-semantic-views permite criar e melhorar views semânticas Snowflake em SQL Навык snowflake-semantic-views позволяет создавать и совершенствовать семантические представления Snowflake в SQL القدرة على إنشاء وتحسين مناظير семантиية雪花 في SQL A skill for creating and enhancing snowflake semantic views in SQL snowflake-semantic-views AI工具 SQL语义视图 数据分析 Snowflake 如何使用snowflake-semantic-views snowflake-semantic-views安装 snowflake-semantic-views教程 A skill for creating and enhancing snowflake semantic views in SQL ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('toshi-hm/dialy/react-component', 'community', 'toshi-hm', 'dialy', 'toshi-hm/dialy', 'react-component', 0, 0, 28, '2026-03-04T13:07:01.756Z', '2026-03-04T14:13:56.621Z', 'ab6f9b841c3b3fe83afba529d32f87497e48f15a3108b0e39c907ade7328018d', '{"id":"toshi-hm/dialy/react-component","name":"react-component","description":{"zh":"React组件：AI智能日记应用，快速查看同一天的过去日记","ja":"Reactコンポーネント：AIエージェントによる日記アプリ、同日過去のエントリを一目で確認","ko":"React 컴포넌트: AI 인공지능 일기 애플리케이션, 동일한 일자의 이전 일기 확인","es":"El componente de React para diario permite ver entradas pasadas para el mismo día a primera vista","fr":"Le composant React pour journal permet de voir les entrées passées pour le même jour d''un seul coup d''œil","de":"Die React-Komponente für Tagebuch ermöglicht es, vergangene Einträge für denselben Tag auf einen Blick zu sehen","pt":"O Reative Diary é um aplicativo de diário que permite ver past entries para o mesmo dia em um só lugar.","ru":"Реактивный Диарий - это приложение-дневник, которое позволяет просматривать прошлые записи для одного дня.","ar":"يوميات تفاعلية هي أداة لإنشاء يوميات شخصية وتعرف على كيفية استخدامها لإنشاء يوميات تفاعلية","en":"A diary app that lets you see past entries for the same day at a glance"},"seo":{"title":{"zh":"React组件：AI智能日记应用","ja":"Reactコンポーネント：AIエージェントによる日記アプリ","ko":"React 컴포넌트: AI 인공지능 일기 애플리케이션","es":"Herramientas de IA: Componente de React para Diario","fr":"Outils d''IA: Composant React pour Journal","de":"KI-Tools: React-Komponente für Tagebuch","pt":"Reactive Diary: Diário de Entradas com React","ru":"ИИ Агенты: Реактивный Диарий с React","ar":"أدوات الذكاء الاصطناعي: يوميات تفاعلية مع React","en":"react-component"},"description":{"zh":"React组件：AI智能日记应用，快速查看同一天的过去日记","ja":"Reactコンポーネント：AIエージェントによる日記アプリ、同日過去のエントリを一目で確認","ko":"React 컴포넌트: AI 인공지능 일기 애플리케이션, 동일한 일자의 이전 일기 확인","es":"El componente de React para diario permite ver entradas pasadas para el mismo día a primera vista","fr":"Le composant React pour journal permet de voir les entrées passées pour le même jour d''un seul coup d''œil","de":"Die React-Komponente für Tagebuch ermöglicht es, vergangene Einträge für denselben Tag auf einen Blick zu sehen","pt":"O Reative Diary é um aplicativo de diário que permite ver past entries para o mesmo dia em um só lugar.","ru":"Реактивный Диарий - это приложение-дневник, которое позволяет просматривать прошлые записи для одного дня.","ar":"يوميات تفاعلية هي أداة لإنشاء يوميات شخصية وتعرف على كيفية استخدامها لإنشاء يوميات تفاعلية","en":"A diary app that lets you see past entries for the same day at a glance"},"definition":{"en":"A diary app that lets you see past entries for the same day at a glance"},"features":{"zh":["快速查看同一天的过去日记","使用React组件构建","AI智能日记应用","支持多种日记格式","易于使用和自定义"],"ja":["同日過去のエントリを一目で確認","Reactコンポーネントを使用した構築","AIエージェントによる日記アプリ","複数の日記フォーマットをサポート","使用とカスタマイズが容易"],"ko":["동일한 일자의 이전 일기 확인","React 컴포넌트를 사용하여 구축","AI 인공지능 일기 애플리케이션","다양한 일기 형식을 지원","사용과 커스터마이징이 쉽습니다"],"es":["Visualización de entradas pasadas para el mismo día","Creación de interfaces de usuario personalizadas con React","Integración con herramientas de IA para análisis de datos","Diseño responsivo para una experiencia de usuario óptima","Compatibilidad con diferentes formatos de datos"],"fr":["Affichage des entrées passées pour le même jour","Création d''interfaces utilisateur personnalisées avec React","Intégration avec des outils d''IA pour l''analyse de données","Conception responsive pour une expérience utilisateur optimale","Compatibilité avec différents formats de données"],"de":["Anzeige von vergangenen Einträgen für denselben Tag","Erstellung von benutzerdefinierten Benutzeroberflächen mit React","Integration mit KI-Tools für Datenanalyse","Responsives Design für eine optimale Benutzererfahrung","Kompatibilität mit verschiedenen Datenformaten"],"pt":["Crie um diário de entradas com React","Veja past entries para o mesmo dia em um só lugar","Personalize seu diário com temas e cores"],"ru":["Создайте реактивный диарий с React","Просмотрите прошлые записи для одного дня","Персонализируйте свой диарий с темами и цветами"],"ar":["ابحث عن يوميات تفاعلية مع React","تعرف على كيفية استخدامها لإنشاء يوميات شخصية","ابحث عن كيفية استخدامها لإنشاء يوميات تفاعلية"]},"keywords":{"zh":["React组件","AI智能日记应用","如何使用React构建日记应用","React日记应用示例","React组件与Angular组件的区别","React日记应用安装","React日记应用设置指南"],"ja":["Reactコンポーネント","AIエージェントによる日記アプリ","Reactを使用して日記アプリを構築する方法","React日記アプリの例","ReactコンポーネントとAngularコンポーネントの違い","React日記アプリのインストール","React日記アプリの設定ガイド"],"ko":["React 컴포넌트","AI 인공지능 일기 애플리케이션","React를 사용하여 일기 애플리케이션을 구축하는 방법","React 일기 애플리케이션 예시","React 컴포넌트와 Angular 컴포넌트의 차이점","React 일기 애플리케이션 설치","React 일기 애플리케이션 설정 가이드"],"es":["cómo usar React para diario","qué es un componente de React","herramientas de IA para diario","alternativas a React para diario","React vs Angular para diario","instalación de React para diario","guía de configuración de React para diario"],"fr":["comment utiliser React pour journal","qu''est-ce qu''un composant React","outils d''IA pour journal","alternatives à React pour journal","React vs Angular pour journal","installation de React pour journal","guide de configuration de React pour journal"],"de":["wie man React für Tagebuch verwendet","was ist eine React-Komponente","KI-Tools für Tagebuch","Alternativen zu React für Tagebuch","React vs Angular für Tagebuch","Installation von React für Tagebuch","Konfigurationsanleitung für React für Tagebuch"],"pt":["Reactive Diary","Diário de Entradas com React","Como criar um diário de entradas com React","Reactive Diary vs outros diários","Instalar Reactive Diary"],"ru":["Реактивный Диарий","Диарий с React","Как создать реактивный диарий с React","Реактивный Диарий vs другие диарии","Установить Реактивный Диарий"],"ar":["يوميات تفاعلية","أدوات الذكاء الاصطناعي","كيفية استخدامها لإنشاء يوميات شخصية","يوميات تفاعلية vs أخرى","تثبيت يوميات تفاعلية"]}},"owner":"toshi-hm","repo":"dialy","repoPath":"toshi-hm/dialy","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.756Z","topics":[],"category":"community","skillMd":{"name":"react-component","description":"React/Next.jsコンポーネントを作成します。Atomic Design階層、TypeScript、Tailwind CSSを使用し、適切なpropsの型定義とアクセシビリティを考慮したコンポーネントを生成します。","bodyPreview":"# React/Next.js Component Creation\n\nReact 19.2.4 と Next.js 16.1.5 を使用した高品質なコンポーネントを作成します。\n\n## 作成手順\n\n### 1. Atomic Design階層の決定\n\nコンポーネントを配置する適切な階層を決定:\n\n- **atoms/**: 基本的なUI要素（Button, Input, Labelなど）。他のコンポーネントに依存しない\n- **molecules/**: atomsの組み合わせ（SearchBar, FormFieldなど）\n- **organisms/**: molecules/atomsを組み合わせた複雑なコンポーネント（Header, DiaryCardなど）\n- **templates/**: ページレベルのレイアウト\n- **app/**: Next.js App Routerのページ（テンプレートの具体的なインスタンス）\n\n**重要**: 上位階層のコンポーネントは下位階層のコンポーネントのみをインポートできます。\n\n### 2. コンポーネントの実装\n\n```types","body":"# React/Next.js Component Creation\n\nReact 19.2.4 と Next.js 16.1.5 を使用した高品質なコンポーネントを作成します。\n\n## 作成手順\n\n### 1. Atomic Design階層の決定\n\nコンポーネントを配置する適切な階層を決定:\n\n- **atoms/**: 基本的なUI要素（Button, Input, Labelなど）。他のコンポーネントに依存しない\n- **molecules/**: atomsの組み合わせ（SearchBar, FormFieldなど）\n- **organisms/**: molecules/atomsを組み合わせた複雑なコンポーネント（Header, DiaryCardなど）\n- **templates/**: ページレベルのレイアウト\n- **app/**: Next.js App Routerのページ（テンプレートの具体的なインスタンス）\n\n**重要**: 上位階層のコンポーネントは下位階層のコンポーネントのみをインポートできます。\n\n### 2. コンポーネントの実装\n\n```typescript\n// src/components/[階層]/ComponentName/ComponentName.tsx\nimport type { FC } from ''react'';\n\nexport type ComponentNameProps = {\n  // Props定義（必須/オプションを明確に）\n  title: string;\n  description?: string;\n  onClick?: () => void;\n  className?: string;\n  children?: React.ReactNode;\n};\n\nexport const ComponentName: FC<ComponentNameProps> = ({\n  title,\n  description,\n  onClick,\n  className = '''',\n  children,\n}) => {\n  return (\n    <div className={`基本スタイル ${className}`}>\n      {/* コンポーネントの実装 */}\n    </div>\n  );\n};\n```\n\n### 3. 実装ガイドライン\n\n**TypeScript**:\n- すべてのpropsに型定義を提供\n- `FC<Props>` を使用\n- エクスポートされるpropsは `export type` で定義\n\n**Styling (Tailwind CSS v4.1)**:\n- ユーティリティクラスを直接使用\n- `className` propでカスタマイズ可能にする\n- レスポンシブデザインには `sm:`, `md:`, `lg:`, `xl:` プレフィックスを使用\n\n**アクセシビリティ**:\n- セマンティックなHTML要素を使用\n- 適切なARIA属性を追加\n- キーボードナビゲーションをサポート\n- 十分なカラーコントラスト比を確保\n\n**パフォーマンス**:\n- 必要に応じて `React.memo` を使用\n- イベントハンドラーは適切にメモ化\n- 重い計算は `useMemo` でキャッシュ\n\n### 4. パスエイリアス\n\nすべてのインポートに `@/` エイリアスを使用:\n\n```typescript\nimport { Button } from ''@/components/atoms/Button'';\nimport { validateDiary } from ''@/lib/validations/diary'';\n```\n\n### 5. ファイル構成\n\nコンポーネントディレクトリには以下を含める:\n\n```\nComponentName/\n├── ComponentName.tsx          # メインコンポーネント\n├── ComponentName.stories.tsx  # Storybook stories（別スキルで作成）\n├── ComponentName.test.tsx     # Vitest tests（別スキルで作成）\n└── index.ts                   # 再エクスポート（オプション）\n```\n\n## 出力\n\n1. コンポーネントファイルを作成\n2. 実装した機能とアクセシビリティ対応を説明\n3. 使用例を提供\n4. 次のステップ（Storybook story作成、テスト作成）を提案\n"},"lastSynced":"2026-03-04T14:13:56.621Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents requiring modular and reusable UI components with React and Next.js","zh":"适合需要模块化和可重用 UI 组件的前端代理，使用 React 和 Next.js","ja":"React と Next.js を使用してモジュラーで再利用可能な UI コンポーネントを必要とするフロントエンド エージェントに適しています","ko":"React와 Next.js를 사용하여 모듈화되고 재사용 가능한 UI 컴포넌트가 필요한 프론트엔드 에이전트에 적합합니다","es":"Ideal para agentes frontend que requieren componentes de interfaz de usuario modulares y reutilizables con React y Next.js","fr":"Idéal pour les agents frontend nécessitant des composants d''interface utilisateur modulaires et réutilisables avec React et Next.js","de":"Ideal für Frontend-Agents, die modulare und wiederverwendbare Benutzeroberflächenkomponenten mit React und Next.js benötigen","pt":"Ideal para Agentes Frontend que requerem componentes de UI modulares e reutilizáveis com React e Next.js","ru":"Идеально для фронтенд-агентов, требующих модульных и многократно используемых компонентов UI с React и Next.js","ar":"مثالي لعميل واجهة المستخدم الأمامية الذي يتطلب مكونات واجهة المستخدم القابلة لإعادة الاستخدام مع React و Next.js"},"recommendation":{"en":"Empowers agents to create high-quality, modular components using React 19.2.4 and Next.js 16.1.5, following Atomic Design principles for organized and maintainable codebases, leveraging hierarchical structures like atoms, molecules, and organisms","zh":"赋予代理创建高质量的模块化组件的能力，使用 React 19.2.4 和 Next.js 16.1.5，遵循原子设计原则，以保持有序和可维护的代码库，利用层次结构，如原子、分子和生物体","ja":"React 19.2.4 と Next.js 16.1.5 を使用して、高品質のモジュラー コンポーネントを作成するエージェントの能力を与え、原子設計の原則に従って、整理され、保守可能なコードベースを保持するために、階層構造 such as 原子、分子、生物を利用する","ko":"React 19.2.4와 Next.js 16.1.5를 사용하여 고품질의 모듈화된 컴포넌트를 생성할 수 있는 에이전트의 능력을 부여하고, 원자 설계의 원칙을 따르며, 계층 구조를 활용하여 조직화되고 유지 보수 가능한 코드베이스를 유지한다","es":"Habilita a los agentes a crear componentes modulares de alta calidad utilizando React 19.2.4 y Next.js 16.1.5, siguiendo los principios de Atomic Design para bases de código organizadas y mantenibles, aprovechando estructuras jerárquicas como átomos, moléculas y organismos","fr":"Permet aux agents de créer des composants modulaires de haute qualité en utilisant React 19.2.4 et Next.js 16.1.5, en suivant les principes de Atomic Design pour des bases de code organisées et maintenables, en exploitant des structures hiérarchiques comme des atomes, des molécules et des organismes","de":"Ermächtigt Agenten, hochwertige, modulare Komponenten mit React 19.2.4 und Next.js 16.1.5 zu erstellen, indem sie die Prinzipien von Atomic Design für organisierte und wartbare Codebasen befolgen, indem sie hierarchische Strukturen wie Atome, Moleküle und Organismen nutzen","pt":"Habilita os agentes a criar componentes de alta qualidade e modulares usando React 19.2.4 e Next.js 16.1.5, seguindo os princípios de design atômico para códigos organizados e mantidos, utilizando estruturas hierárquicas como átomos, moléculas e organismos","ru":"Наделяет агентов возможностью создавать высококачественные, модульные компоненты с использованием React 19.2.4 и Next.js 16.1.5, следуя принципам атомарного дизайна для организованных и поддерживаемых кодовых баз, используя иерархические структуры, такие как атомы, молекулы и организмы","ar":"يمكّن الوكيل من إنشاء مكونات عالية الجودة وقابلة للتحديث باستخدام React 19.2.4 و Next.js 16.1.5، متبعاً مبادئ التصميم الذري لتنظيم وتحديث قواعد البيانات، واستخدام هياكل هرمية مثل الذرات والجزيئات والأعضاء"},"useCases":{"en":["Building reusable UI components for diary apps","Organizing complex interfaces with Atomic Design hierarchy","Creating templated pages with Next.js App Router"],"zh":["为日记应用程序构建可重用 UI 组件","使用原子设计层次结构组织复杂接口","使用 Next.js App Router 创建模板化页面"],"ja":["日記アプリケーションの再利用可能な UI コンポーネントの構築","原子設計階層構造を使用して複雑なインターフェースを整理する","Next.js App Router を使用してテンプレート化されたページを作成する"],"ko":["일기 애플리케이션을 위한 재사용 가능한 UI 컴포넌트 구축","원자 설계 계층 구조를 사용하여 복잡한 인터페이스 구성","Next.js App Router를 사용하여 템플릿화된 페이지 생성"],"es":["Creación de componentes de interfaz de usuario reutilizables para aplicaciones de diario","Organización de interfaces complejas con la jerarquía de Atomic Design","Creación de páginas con plantillas con Next.js App Router"],"fr":["Création de composants d''interface utilisateur réutilisables pour les applications de journal","Organisation d''interfaces complexes avec la hiérarchie de Atomic Design","Création de pages avec des modèles avec Next.js App Router"],"de":["Erstellung wiederverwendbarer Benutzeroberflächenkomponenten für Tagebuch-Apps","Organisation komplexer Schnittstellen mit der Hierarchie von Atomic Design","Erstellung von Seiten mit Vorlagen mit Next.js App Router"],"pt":["Construir componentes de UI reutilizáveis para aplicativos de diário","Organizar interfaces complexas com hierarquia de design atômico","Criar páginas modeladas com Next.js App Router"],"ru":["Построение многократно используемых компонентов UI для приложений-дневников","Организация сложных интерфейсов с помощью иерархии атомарного дизайна","Создание шаблонных страниц с помощью Next.js App Router"],"ar":["إنشاء مكونات واجهة المستخدم القابلة لإعادة الاستخدام لتطبيقات اليومية","تنظيم الواجهات المعقدة بالاعتماد على هرمية التصميم الذري","إنشاء صفحات محددة الشكل باستخدام Next.js App Router"]},"limitations":{"en":["Requires React and Next.js setup","Adherence to Atomic Design hierarchy for component organization"],"zh":["需要 React 和 Next.js 设置","需要遵守原子设计层次结构以组织组件"],"ja":["React と Next.js の設定が必要","コンポーネントの整理のために原子設計階層構造に従う必要がある"],"ko":["React와 Next.js 설정이 필요","컴포넌트의 구성에 원자 설계 계층 구조를 따르야 한다"],"es":["Requiere configuración de React y Next.js","Adhesión a la jerarquía de Atomic Design para la organización de componentes"],"fr":["Nécessite une configuration de React et Next.js","Adhésion à la hiérarchie de Atomic Design pour l''organisation des composants"],"de":["Benötigt React- und Next.js-Setup","Einhaltung der Hierarchie von Atomic Design für die Organisation von Komponenten"],"pt":["Requer configuração do React e Next.js","Adesão à hierarquia de design atômico para organização de componentes"],"ru":["Требует настройки React и Next.js","Соблюдение иерархии атомарного дизайна для организации компонентов"],"ar":["يتطلب إعداد React و Next.js","الالتزام بترتيب التصميم الذري لتنظيم المكونات"]},"version":3},"contentHash":"ab6f9b841c3b3fe83afba529d32f87497e48f15a3108b0e39c907ade7328018d","qualityScore":28}');
