INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SimonXinw/web-html-css-js-demos/threejs-fundamentals', 'threejs-fundamentals', 'SimonXinw', 'web-html-css-js-demos', 'community', 'threejs-fundamentals SimonXinw web-html-css-js-demos community threejs-fundamentals AI工具为开发者提供了一系列JavaScript逻辑demo，用于练习和学习 threejs-fundamentals AIエージェントは、開発者向けのJavaScriptロジックデモを提供します threejs-fundamentals AI 에이전트는 개발자를 위한 자바스크립트 논리 데모를 제공합니다 threejs-fundamentals es una colección de demos prácticos para desarrolladores que desean aprender los fundamentos de threejs threejs-fundamentals est une collection de démos pratiques pour les développeurs qui souhaitent apprendre les fondamentaux de threejs threejs-fundamentals ist eine Sammlung von praktischen Demos für Entwickler, die die Grundlagen von threejs erlernen möchten Os fundamentos do threejs são uma coleção de demos de lógica em JavaScript puro para prática e desenvolvimento de habilidades Основы threejs - это коллекция логических демо на чистом JavaScript для практики и разработки навыков أساسيات threejs هي مجموعة من دمى المنطق المكتوبة بلغة JavaScript الأصلية لممارسة وتطوير المهارات 这是用 原生 js 写的一些可供练习的逻辑的demo threejs-fundamentals AI工具 JavaScript逻辑demo 开发者练习工具 threejs开发资源 如何使用threejs threejs安装 threejs设置指南 这是用 原生 js 写的一些可供练习的逻辑的demo');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('RoleModel/rolemodel-skills/theming-context', 'community', 'RoleModel', 'rolemodel-skills', 'RoleModel/rolemodel-skills', 'theming-context', 0, 0, 28, '2026-03-04T13:07:01.900Z', '2026-03-04T14:56:56.674Z', '05220c59a8f6a0da45cadcc1a43105bf3674ee5720da9c381f81a01e36822aa4', '{"id":"RoleModel/rolemodel-skills/theming-context","name":"theming-context","description":{"zh":"theming-context是一个用于RoleModel Software的AI智能代理技能集合，用于增强开发效率","ja":"theming-contextは、RoleModel Softwareで使用するAIエージェントのスキル集です","ko":"theming-context는 RoleModel Software에서 사용하는 AI 에이전트의 스킬 집합입니다","es":"La colección de habilidades de agentes de IA para trabajar con RoleModel Software, enfocada en la tematización de contexto","fr":"La collection de compétences d''agents d''IA pour travailler avec RoleModel Software, axée sur la thématisation de contexte","de":"Die Sammlung von Fähigkeiten für KI-Agents, um mit RoleModel Software zu arbeiten, fokussiert auf Kontext-Theming","pt":"Theming-context é uma coleção de habilidades de agente focada no trabalho realizado na RoleModel Software, ajudando desenvolvedores a melhorar a eficiência.","ru":"Theming-context - это коллекция навыков агента, ориентированная на работу, выполняемую в RoleModel Software, giúpая разработчикам повысить эффективность.","ar":"ثيمينج-كونتيكست هو مجموعة من مهارات الوكيل التي تركز على العمل المنجز في RoleModel Software، مما يساعد المطورين على تحسين الكفاءة.","en":"A collection of agent skills focused to work we do at RoleModel Software"},"seo":{"title":{"zh":"AI智能代理主题上下文 - theming-context","ja":"AIエージェントのテーマコンテキスト - theming-context","ko":"AI 에이전트 테마 컨텍스트 - theming-context","es":"Herramientas de Tematización de Contexto para Agentes de IA","fr":"Outils de Thématisation de Contexte pour les Agents d''IA","de":"Kontext-Theming-Tools für KI-Agents","pt":"Ferramentas de IA: theming-co