INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('avsm/oxmono/jsont', 'jsont', 'avsm', 'oxmono', 'community', 'jsont avsm oxmono community jsont是基于OxCaml的巨型monorepo，提供强大的开发工具和功能 jsontはOxCamlに基づいた巨大なmonorepoで、強力な開発ツールと機能を提供する jsont는 OxCaml 기반의 대형 모노레포로 강력한 개발 도구와 기능을 제공합니다 jsont es una herramienta de AI que utiliza OxCaml monorepo para mejorar la eficiencia de los proyectos de desarrollo jsont est un outil d''IA qui utilise un monorepo OxCaml pour améliorer l''efficacité des projets de développement jsont ist ein KI-Tool, das ein OxCaml Monorepo verwendet, um die Effizienz von Entwicklungsprojekten zu verbessern O jsont é um monorepo OxCaml gigante para desenvolvedores, oferecendo uma variedade de ferramentas e recursos para melhorar o fluxo de trabalho. Jsont - это гигантский OxCaml монорепозиторий для разработчиков, предлагающий множество инструментов и ресурсов для улучшения рабочего процесса. jsont هو مخزن OxCaml العملاق للمطورين، ويقدم مجموعة من الأدوات والموارد لتحسين تدفق العمل. My giant OxCaml monorepo 如何使用jsont 什么是OxCaml jsont替代品 jsont vs 其他工具 jsont安装 jsont设置指南 OxCaml开发工具 AI智能工具 My giant OxCaml monorepo ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jdecode/altrompy/livewire-development', 'community', 'jdecode', 'altrompy', 'jdecode/altrompy', 'livewire-development', 0, 0, 28, '2026-03-04T13:07:01.943Z', '2026-03-04T15:10:38.713Z', 'dcdcfcc3d330c7a130d757315eca3502c0d7dd97febfd87147986cabbb98f4bc', '{"id":"jdecode/altrompy/livewire-development","name":"livewire-development","description":{"zh":"Livewire开发是一种使用Altron模板的Entropy变体，用于构建高效的Web应用","ja":"Livewire開発は、AltronテンプレートのEntropy変種を使用して、高効率のWebアプリケーションを構築","ko":"Livewire 개발은 Altron 템플릿의 Entropy 변종을 사용하여 효율적인 웹 애플리케이션을 구축하는 방법입니다","es":"Livewire es un framework para crear aplicaciones web reactivas. Altron Template es una herramienta de desarrollo de IA para aumentar la productividad","fr":"Livewire est un framework pour créer des applications web réactives. Altron Template est un outil de développement d''IA pour améliorer la productivité","de":"Livewire ist ein Framework für die Erstellung reaktiver Webanwendungen. Altron-Template ist ein KI-Entwicklungstool, um die Produktivität zu steigern","pt":"O desenvolvimento de Livewire é uma técnica de desenvolvimento web que utiliza o template Altron para melhorar a produtividade","ru":"Разработка на Livewire - это техника веб-разработки, которая использует шаблон Altron для повышения производительности","ar":"تطوير ليف واير هو تقنية تطوير ويب تستخدم قالب Altron لتحسين الإنتاجية","en":"Altron template (play on the word `Entropy`)"},"seo":{"title":{"zh":"AI智能开发工具-Livewire开发","ja":"AIエージェントによるLivewire開発","ko":"AI 에이전트를 사용한 라이브와이어 개발","es":"Desarrollo de Livewire con Altron Template","fr":"Développement Livewire avec Altron Template","de":"Livewire-Entwicklung mit Altron-Template und künstlichen ...","pt":"Desenvolvimento de Livewire: Ferramentas de IA","ru":"Разработка на Livewire: ИИ Агенты","ar":"تطوير ليف واير: أدوات الذكاء الاصطناعي","en":"livewire-develo