INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('harrytran998/crossfire/Clean Architecture', 'Clean Architecture', 'harrytran998', 'crossfire', 'community', 'Clean Architecture harrytran998 crossfire community Clean Architecture的AI智能代理技能，是一种跨界网站开发技术，能够提高开发效率和质量 Clean ArchitectureのAIエージェントスキルは、クロスファイヤーウェブサイトバージョンの開発技術であり、開発効率と品質を向上させることができます Clean Architecture의 AI 에이전트 스킬은 크로스파이어 웹사이트 버전의 개발 기술로서 개발 효율과 품질을 향상시킬 수 있습니다 La Arquitectura Limpia es un enfoque de diseño de software que separa la lógica de negocio de la infraestructura. Inspira en Crossfire, ahora en versión web. L''Architecture Propre est une approche de conception de logiciels qui sépare la logique métier de l''infrastructure. Inspirée de Crossfire, maintenant en version web. Der Saubere Aufbau ist ein Ansatz für die Software-Entwicklung, der die Geschäftslogik von der Infrastruktur trennt. Inspiriert von Crossfire, jetzt in Web-Version. Arquitetura Limpa é um padrão de design que separa a lógica de negócios da infraestrutura, permitindo uma maior flexibilidade e manutenção Чистая Архитектура - это шаблон проектирования, который отделяет логику бизнеса от инфраструктуры, позволяя увеличить гибкость и обслуживание عمارة نظيفة هو نمط تصميم يفصل المنطق التجاري عن البنية التحتية، مما يسمح بمرونة أكبر وصيانة Crossfire - But in website version AI智能代理 Clean Architecture 跨界网站开发 如何使用Clean Architecture Clean Architecture安装 Clean Architecture教程 Crossfire - But in website version');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sorafujitani/claudedot/pr:cmt-plan', 'community', 'sorafujitani', 'claudedot', 'sorafujitani/claudedot', 'pr:cmt-plan', 0, 0, 28, '2026-03-04T13:07:01.961Z', '2026-03-04T15:14:17.884Z', 'a0747a98303732a53bfdd56ca09d62c7cc8a3a92edca38b04deaf818e5c88623', '{"id":"sorafujitani/claudedot/pr:cmt-plan","name":"pr:cmt-plan","description":{"zh":"pr:cmt-plan是一种AI智能工具，用于代码设置和用户范围的管理。它可以帮助开发者提高开发效率和代码质量","ja":"pr:cmt-planは、コード設定とユーザー範囲の管理に特化したAIエージェントです。開発者の開発効率とコード品質を向上させます","ko":"pr:cmt-plan은 코드 설정과 사용자 범위의 관리에 특화된 AI 에이전트입니다. 개발자의 개발 효율과 코드 품질을 향상시킵니다","es":"pr:cmt-plan es una herramienta de IA que permite configurar ajustes de usuario y código con sorafujitani claude","fr":"pr:cmt-plan est un outil d''IA qui permet de configurer les paramètres utilisateur et le code avec sorafujitani claude","de":"pr:cmt-plan ist ein KI-Tool, das die Konfiguration von Benutzereinstellungen und Code mit sorafujitani claude ermöglicht","pt":"O pr:cmt-plan é uma ferramenta de IA que ajuda desenvolvedores a melhorar suas configurações de código e escopo de usuário com Claude e Sorafujitani","ru":"ИИ Агент pr:cmt-plan помогает разработчикам улучшить настройки кода и область пользователя с Claude и Sorafujitani","ar":"أداة الذكاء الاصطناعي pr:cmt-plan تساعد المطورين على تحسين إعدادات الكود و نطاق المستخدم مع Claude و Sorafujitani","en":"sorafujitani claude code settings user scope"},"seo":{"title":{"zh":"AI智能工具：pr:cmt-plan 代码设置","ja":"AIエージェント：pr:cmt-plan コード設定","ko":"AI 에이전트: pr:cmt-plan 코드 설정","es":"Herramientas de IA: pr:cmt-plan para Desarrolladores","fr":"Outils d''IA : pr:cmt-plan pour Développeurs","de":"KI-Tools: pr:cmt-plan für Entwickler","pt":"Ferramentas de IA: pr:cmt-plan para Desenvolvedores","ru":"ИИ Агенты: pr:cmt-plan для Разработчиков","ar":"أدوات الذكاء الاصطناعي: pr:cmt-plan للمطورين","en":"pr:cmt-plan"},"descriptio