INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('agnaldo4j/kanban_vision_api_iex/definition-of-done', 'definition-of-done', 'agnaldo4j', 'kanban_vision_api_iex', 'community', 'definition-of-done agnaldo4j kanban_vision_api_iex community Definition-of-Done Kanban模拟器是AI智能工具，用于提高开发团队的效率和生产力。它支持敏捷开发和项目管理 定義された完了条件Kanbanシミュレーターは、開発チームの効率と生産性を向上させるためのAIエージェントです。アジャイル開発とプロジェクト管理をサポートします 정의된 완료 조건 Kanban 시뮬레이터는 개발 팀의 효율성과 생산성을 향상시키는 AI 에이전트입니다. 애자일 개발과 프로젝트 관리를 지원합니다 El simulador Kanban es una herramienta de AI que ayuda a los equipos a implementar la definición de listo y mejorar su eficiencia Le simulateur Kanban est un outil d''IA qui aide les équipes à mettre en œuvre la définition de terminé et à améliorer leur efficacité Der Kanban-Simulator ist ein KI-Tool, das Teams hilft, die Definition of Done umzusetzen und ihre Effizienz zu verbessern O conceito de definição de pronto é fundamental para melhorar a eficiência do fluxo de trabalho. Nossa ferramenta de simulador Kanban ajuda a entender esse conceito Концепция определения готовности является фундаментальной для повышения эффективности рабочего процесса. Наш инструмент симулятора Kanban помогает понять эту концепцию مفهوم التعريف بالإنجاز هو أساسي لتحسين كفاءة تدفق العمل. أداة محاكي كانبان لدينا تساعد على فهم هذا المفهوم Kanban simulator AI智能工具 Definition-of-Done Kanban模拟器 敏捷开发 项目管理 如何使用Definition-of-Done Kanban模拟器教程 AI智能工具安装 Definition-of-Done标准化流程 Kanban simulator');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jts599/QuickApp/shared-model-refactor', 'community', 'jts599', 'QuickApp', 'jts599/QuickApp', 'shared-model-refactor', 0, 0, 27, '2026-02-22T23:17:28Z', '2026-02-27T04:06:29.668Z', '6be48008c697d4398d15706db0ab049ad1e753a0139123d7c695e0db77fb2ae1', '{"id":"jts599/QuickApp/shared-model-refactor","name":"shared-model-refactor","description":{"zh":"Shared Model Refactor是一个用于构建最小化开销的React应用的框架，帮助开发者提高效率","ja":"Shared Model Refactorは、最小化オーバーヘッドのReactアプリを構築するためのフレームワークです","ko":"Shared Model Refactor는 최소한의 오버헤드가 있는 리액트 앱을 구축하기 위한 프레임워크입니다","es":"Shared-model-refactor es un framework para hacer aplicaciones React con mínimo overhead","fr":"Shared-model-refactor est un framework pour faire des applications React avec un minimum de surcharge","de":"Shared-model-refactor ist ein Framework für die Erstellung von React-Anwendungen mit minimalem Overhead","pt":"O shared-model-refactor é um framework para criar aplicativos React com minimal overhead. Ele oferece uma abordagem eficiente para desenvolver aplicações React.","ru":"Shared-model-refactor — это фреймворк для создания приложений React с минимальными накладными расходами. Он предлагает эффективный подход к разработке приложений React.","ar":"shared-model-refactor هو إطار عمل لإنشاء تطبيقات React مع الحد الأدنى من العبء الإضافي. يقدم نهجًا فعالًا لتطوير تطبيقات React.","en":"A framework for making React Apps with minimal overhead"},"seo":{"title":{"zh":"AI智能代理 - Shared Model Refactor：最小化React应用开销","ja":"AIエージェント - Shared Model Refactor：Reactアプリのオーバーヘッド最小化","ko":"AI 에이전트 - Shared Model Refactor：리액트 앱 최소 오버헤드","es":"Herramientas de AI: shared-model-refactor para React","fr":"Outils d''IA: shared-model-refactor pour React","de":"KI-Tools: shared-model-refactor für React","pt":"Ferramentas de IA: shared-model-refactor para React","ru":"ИИ Агенты: shared-model-refactor для React","ar":"أدوات الذكاء الاصطناعي: shared-model-refactor ل React","en":"shared-model-refactor"},"description":{"zh":"Shared Model Refactor是一个用于构建最小化开销的React应用的框架，帮助开发者提高效率","ja":"Shared Model Refactorは、最小化オーバーヘッドのReactアプリを構築するためのフレームワークです","ko":"Shared Model Refactor는 최소한의 오버헤드가 있는 리액트 앱을 구축하기 위한 프레임워크입니다","es":"Shared-model-refactor es un framework para hacer aplicaciones React con mínimo overhead","fr":"Shared-model-refactor est un framework pour faire des applications React avec un minimum de surcharge","de":"Shared-model-refactor ist ein Framework für die Erstellung von React-Anwendungen mit minimalem Overhead","pt":"O shared-model-refactor é um framework para criar aplicativos React com minimal overhead. Ele oferece uma abordagem eficiente para desenvolver aplicações React.","ru":"Shared-model-refactor — это фреймворк для создания приложений React с минимальными накладными расходами. Он предлагает эффективный подход к разработке прилож...","ar":"shared-model-refactor هو إطار عمل لإنشاء تطبيقات React مع الحد الأدنى من العبء الإضافي. يقدم نهجًا فعالًا لتطوير تطبيقات React.","en":"A framework for making React Apps with minimal overhead"},"definition":{"en":"A framework for making React Apps with minimal overhead"},"features":{"zh":["最小化React应用开销","提高开发效率","优化应用性能","支持React最新版本","易于集成和使用"],"ja":["Reactアプリのオーバーヘッド最小化","開発効率の向上","アプリパフォーマンスの最適化","最新のReactバージョンのサポート","簡単な統合と使用"],"ko":["리액트 앱 최소 오버헤드","개발 효율성 향상","애플리케이션 성능 최적화","최신 리액트 버전 지원","쉬운 통합 및 사용"],"es":["Crea aplicaciones React con mínimo overhead","Optimiza el rendimiento de tus aplicaciones","Simplifica el proceso de desarrollo","Mejora la experiencia del usuario","Compatible con la mayoría de las bibliotecas de React"],"fr":["Créez des applications React avec un minimum de surcharge","Optimisez les performances de vos applications","Simplifiez le processus de développement","Améliorez l''expérience utilisateur","Compatible avec la plupart des bibliothèques de React"],"de":["Erstellen Sie React-Anwendungen mit minimalem Overhead","Optimieren Sie die Leistung Ihrer Anwendungen","Vereinfachen Sie den Entwicklungsprozess","Verbessern Sie die Benutzererfahrung","Kompatibel mit den meisten React-Bibliotheken"],"pt":["Criação de aplicativos React com baixo overhead","Abordagem eficiente para desenvolver aplicações React","Suporte a React","Código aberto","Fácil integração"],"ru":["Создание приложений React с минимальными накладными расходами","Эффективный подход к разработке приложений React","Поддержка React","Открытый код","Легкая интеграция"],"ar":["إنشاء تطبيقات React مع الحد الأدنى من العبء الإضافي","نهج فعال لتطوير تطبيقات React","دعم React","مفتوح المصدر","إضافة سهلة"]},"keywords":{"zh":["如何使用Shared Model Refactor","什么是React应用优化","Shared Model Refactor教程","React应用性能优化","Shared Model Refactor安装","React应用开发框架","Shared Model Refactor vs其他框架","如何提高React应用效率"],"ja":["Shared Model Refactorの使用方法","Reactアプリの最適化とは","Shared Model Refactorチュートリアル","Reactアプリのパフォーマンス最適化","Shared Model Refactorのインストール","Reactアプリ開発フレームワーク","Shared Model Refactorと他のフレームワークの比較","Reactアプリの効率を向上させる方法"],"ko":["Shared Model Refactor 사용법","리액트 애플리케이션 최적화란","Shared Model Refactor 튜토리얼","리액트 애플리케이션 성능 최적화","Shared Model Refactor 설치","리액트 애플리케이션 개발 프레임워크","Shared Model Refactor와 다른 프레임워크 비교","리액트 애플리케이션 효율성 향상 방법"],"es":["herramientas de AI para React","cómo usar shared-model-refactor","qué es shared-model-refactor","shared-model-refactor vs create-react-app","instalación de shared-model-refactor","guía de configuración de shared-model-refactor","alternativas a shared-model-refactor","mejores prácticas para shared-model-refactor"],"fr":["outils d''IA pour React","comment utiliser shared-model-refactor","qu''est-ce que shared-model-refactor","shared-model-refactor vs create-react-app","installation de shared-model-refactor","guide de configuration de shared-model-refactor","alternatives à shared-model-refactor","meilleures pratiques pour shared-model-refactor"],"de":["KI-Tools für React","wie man shared-model-refactor verwendet","was ist shared-model-refactor","shared-model-refactor vs create-react-app","installation von shared-model-refactor","konfigurationsanleitung für shared-model-refactor","alternativen zu shared-model-refactor","best practices für shared-model-refactor"],"pt":["como usar shared-model-refactor","o que é shared-model-refactor","shared-model-refactor alternativa","shared-model-refactor vs create-react-app","instalar shared-model-refactor","guia de configuração do shared-model-refactor"],"ru":["как использовать shared-model-refactor","что такое shared-model-refactor","альтернатива shared-model-refactor","shared-model-refactor vs create-react-app","установить shared-model-refactor","руководство по настройке shared-model-refactor"],"ar":["كيفية استخدام shared-model-refactor","ما هو shared-model-refactor","بديل shared-model-refactor","shared-model-refactor مقابل create-react-app","تثبيت shared-model-refactor","دليل إعداد shared-model-refactor"]}},"owner":"jts599","repo":"QuickApp","repoPath":"jts599/QuickApp","stars":0,"forks":0,"updatedAt":"2026-02-22T23:17:28Z","topics":[],"category":"community","skillMd":{"name":"shared-model-refactor","description":"Refactor shared server/client TypeScript contracts into a common models directory and eliminate cross-boundary imports (for example client importing server classes). Use when client code depends on server module exports for types or when generated client code needs DTO/view-data/method contracts without bundling server implementation files.","bodyPreview":"# Shared Model Refactor\n\nRefactor code so server and client both import shared contracts from `sampleImplementation/models/` instead of importing each other.\n\n## Workflow\n\n1. Find boundary violations.\n- Run:\n  - `rg -n \"from [''\\\"].*server/|from [''\\\"].*client/\" sampleImplementation src test -S`\n- Identify client imports from `sampleImplementation/server/*` and server imports from `sampleImplementation/client/*`.\n\n2. Identify movable symbols.\n- Move only pure contracts:\n  - interfaces\n  - type ali","body":"# Shared Model Refactor\n\nRefactor code so server and client both import shared contracts from `sampleImplementation/models/` instead of importing each other.\n\n## Workflow\n\n1. Find boundary violations.\n- Run:\n  - `rg -n \"from [''\\\"].*server/|from [''\\\"].*client/\" sampleImplementation src test -S`\n- Identify client imports from `sampleImplementation/server/*` and server imports from `sampleImplementation/client/*`.\n\n2. Identify movable symbols.\n- Move only pure contracts:\n  - interfaces\n  - type aliases\n  - enums/constants used as DTO/schema contracts\n- Do not move implementation/runtime code:\n  - decorated classes\n  - business logic\n  - DB/network utilities\n\n3. Create model files.\n- Place extracted contracts in `sampleImplementation/models/`.\n- Use feature-based files (for example `sampleImplementation/models/sampleView.ts`).\n- Keep files side-effect free.\n\n4. Update imports.\n- Update server and client to import contracts from `sampleImplementation/models/*`.\n- For NodeNext, use explicit `.js` extensions in TS imports.\n- Prefer `import type` for type-only imports.\n\n5. Update client generation templates/runtime.\n- Ensure generated client code imports contracts from `models/`, not server class modules.\n- If generator currently infers types via server class imports, switch generation to explicit model imports per controller.\n\n6. Regenerate generated client files.\n- Run generation command(s) after template changes.\n\n7. Validate.\n- Run:\n  - `npm run typecheck`\n  - `npm test`\n  - `cd sampleImplementation && npm run build`\n- Confirm no client file imports from `sampleImplementation/server/*`.\n\n## File Organization Rules\n\n- `sampleImplementation/models/` is the only shared contract boundary.\n- Server code may import from `models/` and `src/`.\n- Client code may import from `models/` and `src/client` runtime APIs.\n- Client code must not import from `sampleImplementation/server/`.\n\n## Refactor Heuristics\n\n- Keep model names aligned with domain language.\n- Split large contract files by feature, not by type-kind.\n- Do not duplicate contracts in both server and client.\n- If a contract is only used on one side, keep it local.\n\n## Acceptance Criteria\n\n- Zero cross-boundary implementation imports between `server/` and `client/`.\n- Shared DTO/view-data/method contracts live under `sampleImplementation/models/`.\n- Generated client output compiles and no longer depends on server class imports.\n- Full typecheck/tests/build pass.\n"},"lastSynced":"2026-02-27T04:06:29.668Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Refactoring Agents needing to minimize overhead in React applications","zh":"非常适合需要在React应用程序中最小化开销的代码重构代理","ja":"Reactアプリケーションでオーバーヘッドを最小限に抑える必要があるコードリファクタリングエージェントに最適","ko":"React 애플리케이션에서 오버헤드를 최소화해야 하는 코드 리팩토링 에이전트에 적합","es":"Perfecto para Agentes de Refactorización de Código que necesitan minimizar la sobrecarga en aplicaciones React","fr":"Parfait pour les Agents de Réfactoration de Code nécessitant une minimisation de la surcharge dans les applications React","de":"Perfekt für Code-Refactoring-Agents, die die Overhead in React-Anwendungen minimieren müssen","pt":"Perfeito para Agentes de Refatoração de Código que precisam minimizar o overhead em aplicações React","ru":"Идеально для агентов рефакторинга кода, которым необходимо минимизировать overhead в приложениях React","ar":"مثالي لعميل استعادة بناء الكود الذي يحتاج إلى تقليل الحمل الزائد في تطبيقات React"},"recommendation":{"en":"Empowers agents to refactor code for shared contracts, utilizing `sampleImplementation/models/` and optimizing imports for server and client, leveraging React and rg for efficient boundary violation identification and movable symbol detection","zh":"赋予代理重构代码用于共享契约的能力，利用`sampleImplementation/models/`，并针对服务器和客户端优化导入，利用React和rg进行高效的边界违规识别和可移动符号检测","ja":"エージェントが共有契約のコードをリファクタリングできるようにし、`sampleImplementation/models/`を利用し、サーバーとクライアントのインポートを最適化し、Reactとrgを使用して効率的な境界違反の検出と可動シンボルの検出を行う","ko":"에이전트가 공유 계약의 코드를 리팩토링할 수 있도록 하며, `sampleImplementation/models/`를 활용하고 서버와 클라이언트의 가져오기를 최적화하며 React와 rg를 사용하여 효율적인 경계 위반 식별 및 이동 가능한 기호 감지","es":"Empodera a los agentes para refactorizar el código para contratos compartidos, utilizando `sampleImplementation/models/` y optimizando las importaciones para servidor y cliente, aprovechando React y rg para una identificación eficiente de violaciones de límites y detección de símbolos movibles","fr":"Permet aux agents de refactoriser le code pour les contrats partagés, en utilisant `sampleImplementation/models/` et en optimisant les importations pour le serveur et le client, en exploitant React et rg pour une identification efficace des violations de limites et de détection de symboles mobiles","de":"Ermächtigt die Agenten, den Code für gemeinsame Verträge zu refaktorisieren, indem `sampleImplementation/models/` verwendet und die Importe für Server und Client optimiert werden, und zwar unter Ausnutzung von React und rg für eine effiziente Erkennung von Grenzverletzungen und beweglicher Symbolerkennung","pt":"Habilita os agentes a refatorar o código para contratos compartilhados, utilizando `sampleImplementation/models/` e otimizando as importações para servidor e cliente, aproveitando React e rg para identificação eficiente de violações de limite e detecção de símbolos móveis","ru":"Позволяет агентам рефакторить код для общих контрактов, используя `sampleImplementation/models/` и оптимизируя импорты для сервера и клиента, используя React и rg для эффективной идентификации нарушений границ и обнаружения подвижных символов","ar":"تمكّن الوكلاء من إعادة هيكلة الكود لمواصفات مشتركة، باستخدام `sampleImplementation/models/` وضبط الاستيرادات للخادم والعميل، واستخدام React و rg للكشف الفعال عن انتهاكات الحدود واكتشاف الرموز المتحركة"},"useCases":{"en":["Refactoring React codebases for minimal overhead","Identifying boundary violations in server and client imports","Migrating pure contracts to shared models"],"zh":["为最小化开销而重构React代码库","在服务器和客户端导入中识别边界违规","将纯合同迁移到共享模型"],"ja":["最小のオーバーヘッドでReactコードベースをリファクタリングする","サーバーとクライアントのインポートで境界違反を識別する","純粋な契約を共有モデルに移行する"],"ko":["최소한의 오버헤드로 React 코드베이스를 리팩토링하는 것","서버와 클라이언트의 가져오기에서 경계 위반을 식별","순수 계약을 공유 모델로 마이그레이션"],"es":["Refactorización de bases de código React para una sobrecarga mínima","Identificación de violaciones de límites en importaciones de servidor y cliente","Migración de contratos puros a modelos compartidos"],"fr":["Réfactoration de bases de code React pour une surcharge minimale","Identification de violations de limites dans les importations de serveur et de client","Migration de contrats purs vers des modèles partagés"],"de":["Refaktorisierung von React-Codebasen für minimale Overhead","Identifizierung von Grenzverletzungen in Server- und Client-Importen","Migration von reinen Verträgen zu gemeinsamen Modellen"],"pt":["Refatoração de código React para overhead mínimo","Identificação de violações de limite em importações de servidor e cliente","Migração de contratos puros para modelos compartilhados"],"ru":["Рефакторинг кода React для минимизации overhead","Обнаружение нарушений границ в импортах сервера и клиента","Миграция чистых контрактов в общие модели"],"ar":["إعادة هيكلة الكود React لتحميل زائد أدنى","تحديد انتهاكات الحدود في استيرادات الخادم والعميل","هجرة المواصفات النقية إلى نماذج مشتركة"]},"limitations":{"en":["Requires React application setup","Limited to JavaScript and React ecosystem","Needs rg for efficient code searching"],"zh":["需要React应用程序设置","仅限于JavaScript和React生态系统","需要rg进行高效的代码搜索"],"ja":["Reactアプリケーションの設定が必要","JavaScriptとReactエコシステムのみに限定される","効率的なコード検索にはrgが必要"],"ko":["React 애플리케이션 설정이 필요","JavaScript와 React 생태계로만 제한","효율적인 코드 검색을 위해 rg가 필요"],"es":["Requiere configuración de aplicación React","Limitado a JavaScript y ecosistema React","Necesita rg para una búsqueda de código eficiente"],"fr":["Nécessite une configuration d''application React","Limité à JavaScript et à l''écosystème React","Nécessite rg pour une recherche de code efficace"],"de":["Benötigt React-Anwendungskonfiguration","Begrenzt auf JavaScript und React-Ökosystem","Benötigt rg für eine effiziente Code-Suche"],"pt":["Exige configuração de aplicação React","Limitado ao ecossistema JavaScript e React","Necessita de rg para busca de código eficiente"],"ru":["Требует настройки приложения React","Ограничен экосистемой JavaScript и React","Требует rg для эффективного поиска кода"],"ar":["يتطلب إعداد تطبيق React","محدود بنظام JavaScript و React","يحتاج إلى rg للبحث الفعال عن الكود"]},"version":3},"contentHash":"6be48008c697d4398d15706db0ab049ad1e753a0139123d7c695e0db77fb2ae1","qualityScore":27}');
