INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jts599/QuickApp/shared-model-refactor', 'shared-model-refactor', 'jts599', 'QuickApp', 'community', 'shared-model-refactor jts599 QuickApp community Shared Model Refactor是一个用于构建最小化开销的React应用的框架，帮助开发者提高效率 Shared Model Refactorは、最小化オーバーヘッドのReactアプリを構築するためのフレームワークです Shared Model Refactor는 최소한의 오버헤드가 있는 리액트 앱을 구축하기 위한 프레임워크입니다 Shared-model-refactor es un framework para hacer aplicaciones React con mínimo overhead Shared-model-refactor est un framework pour faire des applications React avec un minimum de surcharge Shared-model-refactor ist ein Framework für die Erstellung von React-Anwendungen mit minimalem Overhead O shared-model-refactor é um framework para criar aplicativos React com minimal overhead. Ele oferece uma abordagem eficiente para desenvolver aplicações React. Shared-model-refactor — это фреймворк для создания приложений React с минимальными накладными расходами. Он предлагает эффективный подход к разработке приложений React. shared-model-refactor هو إطار عمل لإنشاء تطبيقات React مع الحد الأدنى من العبء الإضافي. يقدم نهجًا فعالًا لتطوير تطبيقات React. A framework for making React Apps with minimal overhead 如何使用Shared Model Refactor 什么是React应用优化 Shared Model Refactor教程 React应用性能优化 Shared Model Refactor安装 React应用开发框架 Shared Model Refactor vs其他框架 如何提高React应用效率 A framework for making React Apps with minimal overhead');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('j7-dev/everything-github-copilot/frontend-slides', 'community', 'j7-dev', 'everything-github-copilot', 'j7-dev/everything-github-copilot', 'frontend-slides', 0, 0, 27, '2026-03-04T04:55:53Z', '2026-03-04T15:31:59.480Z', 'da378954096f51844ab9214d6ae30f317d7f5373af41fbc7e989d20518adb9b8', '{"id":"j7-dev/everything-github-copilot/frontend-slides","name":"frontend-slides","description":{"zh":"frontend-slides 是一个 AI 智能工具，用于重写 Claude 代码并实现 GitHub Copilot 集成，帮助开发者提高效率","ja":"frontend-slides は、Claude コードを書き換え、GitHub Copilot と統合する AI エージェントです。開発者の効率を向上させることができます","ko":"frontend-slides는 Claude 코드를 재작성하고 GitHub Copilot과 통합하는 AI 인텔리전트 도구로, 개발자의 효율성을 높여줍니다","es":"frontend-slides es una herramienta de AI que reescribe el código Claude para GitHub Copilot, mejorando la eficiencia en proyectos de desarrollo frontend","fr":"frontend-slides est un outil IA qui réécrit le code Claude pour GitHub Copilot, améliorant l''efficacité dans les projets de développement frontend","de":"frontend-slides ist ein KI-Tool, das den Claude-Code für GitHub Copilot neu schreibt, um die Effizienz in Frontend-Entwicklungsprojekten zu verbessern","pt":"O frontend-slides é uma ferramenta de IA que reescreve o código para GitHub Copilot, melhorando a eficiência do desenvolvimento.","ru":"Frontend-slides - это ИИ Агент, который переписывает код для GitHub Copilot, повышая эффективность разработки.","ar":"frontend-slides هي أداة ذكاء اصطناعي تقوم بكتابة код جديد ل GitHub Copilot، وتحسين كفاءة التطوير.","en":"rewrite everything-claude-code for github-copilot"},"seo":{"title":{"zh":"AI智能前端幻灯片开发 - frontend-slides","ja":"AIエージェントによるフロントエンドスライド開発 - frontend-slides","ko":"AI 인텔리전트 프론트엔드 슬라이드 개발 - frontend-slides","es":"Herramientas de AI: frontend-slides para GitHub Copilot","fr":"Outils IA: frontend-slides pour GitHub Copilot","de":"KI-Tools: frontend-s