INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('coollabsio/laravel-template/inertia-vue-development', 'community', 'coollabsio', 'laravel-template', 'coollabsio/laravel-template', 'inertia-vue-development', 0, 0, 27, '2026-03-04T13:07:01.838Z', '2026-03-04T14:46:20.195Z', '78cee50a9b19af2cf597253231710b7e3fe1f43403455f968b1324e268655314', '{"id":"coollabsio/laravel-template/inertia-vue-development","name":"inertia-vue-development","description":{"zh":"Inertia Vue开发模板是为Laravel应用提供的强大工具，帮助开发者快速构建高性能的应用","ja":"Inertia Vue開発テンプレートは、Laravelアプリ向けの強力なツールであり、開発者が高パフォーマンスのアプリを迅速に構築できるようにします","ko":"Inertia Vue 개발 템플릿은 Laravel 애플리케이션을 위한 강력한 도구로, 개발자가 고성능의 애플리케이션을 빠르게 구축할 수 있도록 합니다","es":"Plantilla para aplicaciones Laravel con Inertia y Vue, herramientas de desarrollo de AI Agent","fr":"Modèle pour applications Laravel avec Inertia et Vue, outils de développement d''Agent IA","de":"Vorlage für Laravel-Anwendungen mit Inertia und Vue, Tools für die Entwicklung von KI-Agenten","pt":"Inertia Vue é um template para desenvolvimento de aplicações Laravel, permitindo a criação de aplicações web escaláveis e eficientes","ru":"ИИ Агенты представляют собой Inertia Vue, шаблон для разработки приложений Laravel, позволяющий создавать масштабируемые и эффективные веб-приложения","ar":"أدوات الذكاء الاصطناعي تقدم انيرتيا فيو، وهي قالب لتطوير تطبيقات لارافيل، تمكن من إنشاء تطبيقات الويب القابلة للتوسيع والفعالة","en":"Template for Laravel apps"},"seo":{"title":{"zh":"AI智能开发工具：Inertia Vue开发模板","ja":"AIエージェント：Inertia Vue開発テンプレート","ko":"AI 에이전트: Inertia Vue 개발 템플릿","es":"Desarrollo de Inertia con Vue para Laravel","fr":"Développement Inertia-Vue pour Laravel","de":"Inertia-Vue-Entwicklung für Laravel","pt":"Desenvolvimento Inertia Vue para Aplicativos Laravel","ru":"ИИ Агенты: Разработка Inertia Vue для Laravel","ar":"أدوات الذكاء الاصطناعي: تطوير انيرتيا فيو للتطبيقات لارافيل","e