INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('libondev/pxd/vue-best-practices', 'vue-best-practices', 'libondev', 'pxd', 'community', 'vue-best-practices libondev pxd community component-library ui vue vue-components vue2 vue3 Vue最佳实践的AIエージェント的UI组件库，为Vue2.7+和Vue3.2+提供通用UI组件 VueベストプラクティスのAIエージェントのUIコンポーネントライブラリは、Vue2.7+とVue3.2+用のユニバーサルUIコンポーネントを提供します Vue 베스트 프랙티스의 AI 에이전트의 UI 컴포넌트 라이브러리는 Vue2.7+와 Vue3.2+를 위한 유니버설 UI 컴포넌트를 제공합니다 Biblioteca de componentes UI para Vue2.7+ y Vue3.2+, para desarrolladores que buscan las mejores prácticas y herramientas de inteligencia artificial Bibliothèque de composants UI pour Vue2.7+ et Vue3.2+, pour les développeurs qui recherchent les meilleures pratiques et les outils d''intelligence artificielle Bibliothek von UI-Komponenten für Vue2.7+ und Vue3.2+, für Entwickler, die nach den besten Praktiken und KI-Tools suchen Biblioteca de componentes de IU para Vue, compatível com Vue2.7+ e Vue3.2+ Универсальная библиотека компонентов UI для Vue, совместимая с Vue2.7+ и Vue3.2+ مكتبة مكونات واجهة المستخدم الشاملة لفيو، متوافقة مع فيو 2.7+ و فيو 3.2+ A universal UI component library for Vue2.7+ & Vue3.2+ Vue最佳实践 AIエージェント的UI组件库 Vue UI组件 Vue开发效率 Vue浏览器兼容 Vue更新和维护 如何使用Vue UI组件库 Vue UI组件库的优点 A universal UI component library for Vue2.7+ & Vue3.2+');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('o1xhack/telegram-watch/telegram-watch-dev', 'community', 'o1xhack', 'telegram-watch', 'o1xhack/telegram-watch', 'telegram-watch-dev', 7, 0, 26, '2026-02-13T08:45:30Z', '2026-02-26T08:36:09.105Z', '25b838c2495257daa4f55e0974b32aacd795fa4de5cdbd0c64142ede56a9db6f', '{"id":"o1xhack/telegram-watch/telegram-watch-dev","name":"telegram-watch-dev","description":{"zh":"本地Telegram监控工具，使用Telethon开发，监控特定用户和群组，捕获消息和媒体，生成周期性报告","ja":"ローカルのTelegramウォッチャー、Telethonを使用して開発、特定のユーザーとグループを監視、メッセージとメディアをキャプチャ、定期的なレポートを生成","ko":"로컬 Telegram 감시 도구, Telethon을 사용하여 개발, 특정 사용자 및 그룹을 감시, 메시지 및 미디어를 캡처, 주기적인 보고서 생성","es":"Telegram-watch-dev es una herramienta de monitoreo de Telegram que captura mensajes y medios en una base de datos SQLite y envía informes periódicos en HTML.","fr":"Telegram-watch-dev est un outil de surveillance de Telegram qui capture les messages et les médias dans une base de données SQLite et envoie des rapports périodiques en HTML.","de":"Telegram-watch-dev ist ein Überwachungstool für Telegram, das Nachrichten und Medien in einer SQLite-Datenbank erfasst und regelmäßige Berichte im HTML-Format sendet.","pt":"O telegram-watch-dev é uma ferramenta de monitoramento de Telegram local que captura mensagens e mídia em um grupo ou canal alvo e envia relatórios periódicos","ru":"Телеграм-часы - это локальный ИИ Агент для Telegram, который может отслеживать конкретных пользователей в группе или канале и отправлять отчеты","ar":"أداة مراقبة تليجرام هي أداة локالية تقوم ب 捕获 الرسائل ووسائط في مجموعة أو قناة محددة وترسل تقارير دورية","en":"Fully local Telegram watcher powered by Telethon — monitor specific users in a target group/channel, capture messages/media into SQLite, and push periodic HTML reports back to a control chat."},"seo":{"title":{"zh":"AI智能工具：Telegram监控开发","ja":"AIエージェント：Telegramウォッチ開発","ko":"AI 에이전트: Tel