INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('odysseyalive/omarchy-seashells-theme/self-heal', 'self-heal', 'odysseyalive', 'omarchy-seashells-theme', 'community', 'self-heal odysseyalive omarchy-seashells-theme community SeaShells主题为omarchy提供了一种舒缓的海洋色彩方案，包括深色和浅色变体 SeaShellsテーマはomarchyに海洋色を提供し、ダークとライトのバリエーションを含みます SeaShells 테마는 omarchy에 바다 색상을 제공하며, 다크와 라이트 변형을 포함합니다 Tema SeaShells para Omarchy con colores inspirados en el océano y variantes oscuras y claras para una experiencia de escritorio cohesiva Thème SeaShells pour Omarchy avec des couleurs inspirées par l''océan et des variantes sombres et claires pour une expérience de bureau cohérente SeaShells-Thema für Omarchy mit ozeaninspirierten Farben und dunklen und hellen Varianten für eine kohärente Desktop-Erfahrung O tema SeaShells para Omarchy é uma paleta de cores inspirada no tema clássico do terminal SeaShells, com tons de azul e bege. Тема SeaShells для Omarchy - это цветовая палитра, вдохновленная классической темой терминала SeaShells, с теплыми бежевыми и прохладными циановыми тонами. سمة SeaShells ل Omarchy هي لوحة ألوان مستوحاة من سمة الطرفية الكلاسيكية SeaShells، مع درجات الأزرق والبيج. SeaShells theme for omarchy - A soothing oceanic colorscheme with dark and light variants. Features warm beige and cool cyan tones inspired by the classic SeaShells terminal theme. Includes configurations for Hyprland, Neovim, Kitty, Alacritty, Waybar, and more. Complete omarchy theme pack fo... AI智能代理 自愈功能 SeaShells主题 omarchy桌面 如何使用SeaShells主题 什么是AI智能代理 SeaShells主题安装 omarchy主题设置指南 SeaShells theme for omarchy - A soothing oceanic colorscheme with dark and light variants. Features warm beige and cool cyan tones inspired by the classic SeaShells terminal theme. Includes configurations for Hyprland, Neovim, Kitty, Alacritty, Waybar, and more. Complete omarchy theme pack for a cohesive desktop experience.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('igorder-dev/apex/devil-advocate', 'community', 'igorder-dev', 'apex', 'igorder-dev/apex', 'devil-advocate', 0, 0, 26, '2026-02-20T21:48:26Z', '2026-02-26T13:11:06.509Z', '02395d757066ecb8c53db7c9db11e3446514b32e7da01c738f7aab6de6f5915d', '{"id":"igorder-dev/apex/devil-advocate","name":"devil-advocate","description":{"zh":"devil-advocate AI智能代理是Apex的idea-to-documentation代理，帮助开发者将原始想法转化为生产就绪的文档包","ja":"devil-advocate AIエージェントはApexのIdea-to-Documentationエージェントであり、開発者がアイデアを文書化するのに役立ちます","ko":"devil-advocate AI 에이전트는 Apex의 아이디어-문서 에이전트로서 개발자가 원시 아이디어를 생산 준비된 문서 패키지로 변환하는 데 도움을 줍니다","es":"El agente AI devil-advocate es una herramienta que convierte ideas en documentación lista para producción, ayudando a los desarrolladores a trabajar de manera más eficiente.","fr":"L''agent IA devil-advocate est un outil qui convertit les idées en documentation prête pour la production, aidant les développeurs à travailler de manière plus efficace.","de":"Der KI-Agent devil-advocate ist ein Tool, das Ideen in produktionsbereite Dokumentation umwandelt, um Entwicklern eine effizientere Arbeitsweise zu ermöglichen.","pt":"O Devil-Advocate é um agente de documentação que converte ideias em pacotes de documentação prontos para produção, utilizando tecnologias como React, Python e Node.js.","ru":"ИИ Агент Devil-Advocate конвертирует идеи в готовые пакеты документации, используя технологии như React, Python и Node.js.","ar":"وكلاء التوثيق devil-advocate يتحول الأفكار إلى حزم وثائق جاهزة للإنتاج، باستخدام تقنيات مثل React، Python و Node.js.","en":"Apex: Idea-to-Documentation Agent — converts raw ideas into production-ready documentation packs"},"seo":{"title":{"zh":"AI智能代理devil-advocate：从想法到文档","ja":"AIエージェントdevil-advocate：アイデアを文書化","ko":"AI 에이전트 devil-advocate: 아이디어를 문서로","es":"Agente AI devil-advocate: Documentación lista para produc