INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Piebald-AI/splitrail/tui', 'tui', 'Piebald-AI', 'splitrail', 'community', 'tui Piebald-AI splitrail community tui是快速跨平台实时Token使用跟踪器和成本监控工具，支持多个CLI平台 tuiは高速クロスプラットフォームリアルタイムトークン使用トラッカーとコストモニタリングツールです。複数のCLIプラットフォームをサポートしています tui는 빠른 크로스 플랫폼 실시간 토큰 사용 추적기와 비용 모니터링 도구입니다. 여러 CLI 플랫폼을 지원합니다 TUI es un tracker de tokens de IA rápido y multiplataforma para Gemini CLI, Claude Code y otros TUI est un outil de suivi de jetons d''IA rapide et multiplateforme pour Gemini CLI, Claude Code et autres TUI ist ein schnelles und plattformübergreifendes KI-Token-Tracking-Tool für Gemini CLI, Claude Code und mehr O tui é uma ferramenta rápida e cross-platform para rastrear o uso de tokens em tempo real para CLI de desenvolvimento tui - быстрый и кроссплатформенный инструмент для отслеживания использования токенов в режиме реального времени для CLI-разработки tui هو أداة سريعة ومتعددة المنصات لتتبع استخدام الرموز في الوقت الفعلي لCLI التطوير Fast, cross-platform, real-time token usage tracker and cost monitor for Gemini CLI / Claude Code / Codex CLI / Qwen Code / Cline / Roo Code / Kilo Code / GitHub Copilot / OpenCode / Pi Agent / Piebald. 如何使用tui 什么是Token使用跟踪 tui替代品 tui vs 其他工具 tui安装 tui设置指南 AI智能工具 实时成本监控 跨平台支持 Fast, cross-platform, real-time token usage tracker and cost monitor for Gemini CLI / Claude Code / Codex CLI / Qwen Code / Cline / Roo Code / Kilo Code / GitHub Copilot / OpenCode / Pi Agent / Piebald.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('snakeying/Textum/textum', 'community', 'snakeying', 'Textum', 'snakeying/Textum', 'textum', 0, 0, 26, '2026-03-04T13:07:01.680Z', '2026-03-04T13:24:31.990Z', '1e1313ba41f3bfe5c941222554da5c332a5e447d0f6dc6a51cad94cfee2a1d88', '{"id":"snakeying/Textum/textum","name":"textum","description":{"zh":"Textum是一种结构化工作流，通过4个阶段和验证门槛来确保AI不会忘记您的需求","ja":"Textumは構造化ワークフローであり、4つの段階と検証ゲートでAIが要件を忘れないようにします","ko":"Textum은 구조화된 워크플로우로 4개의 단계와 검증 게이트를 통해 AI가 요구사항을 잊지 않도록 합니다","es":"Textum es un flujo de trabajo estructurado que evita que la IA olvide tus requisitos. Con 4 fases y puertas de validación, permite controlar el proceso de agente de IA","fr":"Textum est un flux de travail structuré qui empêche l''IA d''oublier vos exigences. Avec 4 phases et des portes de validation, il permet de contrôler le processus d''agent IA","de":"Textum ist ein strukturierter Workflow, der verhindert, dass die KI Ihre Anforderungen vergisst. Mit 4 Phasen und Validierungstoren ermöglicht es die Kontrolle des KI-Agent-Prozesses","pt":"O Textum é uma ferramenta de IA que oferece um fluxo de trabalho estruturado com 4 fases e portas de validação para controlar o processo de desenvolvimento","ru":"Textum - это инструмент ИИ, который предлагает структурированный рабочий процесс с 4 фазами и валидационными воротами для контроля процесса разработки","ar":"Textum هو أداة ذكاء اصطناعي تقدم عملية عمل مهيكلة مع 4 مراحل وبوابات التحقق للسيطرة على عملية التطوير","en":"Structured workflow that stops AI from forgetting your requirements. 4 phases with validation gates. Not smarter AI, just controllable process. Weave ideas into code that actually works."},"seo":{"title":{"zh":"Textum AIエージェント：结构化工作流","ja":"Textum AIエージェント：構造化ワークフロー","ko":"Textum AI 에이전트: 구조화된 워크플로우","es":"Textum: Herramientas de Agente de IA para Desarrolladores","fr":"Textum: Outils d''Ag