INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('johnhuang316/code-index-mcp/release-prep', 'release-prep', 'johnhuang316', 'code-index-mcp', 'community', 'release-prep johnhuang316 code-index-mcp community release-prep AI工具是一个MCP服务器，帮助大型语言模型索引、搜索和分析代码库，实现快速部署和开发 release-prep AIエージェントはMCPサーバーです。コードリポジトリをインデックスし、検索し、分析します - 大型言語モデル向けの最適ソリューション release-prep AI 에이전트는 MCP 서버입니다. 코드 저장소를 인덱싱, 검색 및 분석합니다 - 대형 언어 모델을 위한 최적의 솔루션 release-prep es un servidor MCP que ayuda a los grandes modelos de lenguaje a indexar, buscar y analizar repositorios de código con mínimo setup release-prep est un serveur MCP qui aide les grands modèles de langage à indexer, rechercher et analyser les référentiels de code avec un minimum de configuration release-prep ist ein MCP-Server, der großen Sprachmodellen hilft, Code-Repositorys mit minimalem Setup zu indizieren, zu durchsuchen und zu analysieren O release-prep é um servidor MCP que ajuda a indexar, buscar e analisar repositórios de código com mínimo setup Release-prep - это сервер MCP, который помогает индексировать, искать и анализировать кодовые репозитории с минимальной настройкой release-prep هو خادم MCP الذي يساعد في فهرسة وتنظيم وتحليل مستودعات الشفرة مع إعدادات دقيقة A Model Context Protocol (MCP) server that helps large language models index, search, and analyze code repositories with minimal setup release-prep AI工具 代码库搜索和分析 大型语言模型索引 MCP服务器 代码库索引和搜索 大型语言模型支持 A Model Context Protocol (MCP) server that helps large language models index, search, and analyze code repositories with minimal setup');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hugocool/FateForger/notion-constraint-memory', 'community', 'hugocool', 'FateForger', 'hugocool/FateForger', 'notion-constraint-memory', 0, 0, 26, '2026-03-04T13:07:01.756Z', '2026-03-04T14:13:55.705Z', 'f184cbce2535c2be1594c71643aa4e8307087da4ee40cc44c793c5118eaae42e', '{"id":"hugocool/FateForger/notion-constraint-memory","name":"notion-constraint-memory","description":{"zh":"Notion 约束内存 AI 工具旨在提高生产力。通过优化内存使用，开发者可以更高效地工作","ja":"Notion 制約メモリ AI エージェントは、生産性を高めることを目的としています。メモリ使用を最適化することで、開発者はより効率的に作業できます","ko":"Notion 제약 메모리 AI 에이전트는 생산성을 높이는 것을 목표로합니다. 메모리 사용을 최적화함으로써 개발자는 더 효율적으로 작업할 수 있습니다","es":"Notion Constraint Memory es una herramienta de IA que ayuda a mejorar la productividad mediante la optimización de la memoria","fr":"Notion Constraint Memory est un outil d''IA qui aide à améliorer la productivité en optimisant la mémoire","de":"Notion Constraint Memory ist ein KI-Tool, das die Produktivität durch die Optimierung des Speichers verbessert","pt":"O Notion Constraint Memory é uma ferramenta de IA que ajuda a melhorar a produtividade dos desenvolvedores","ru":"Notion Constraint Memory - это инструмент ИИ, который помогает повысить производительность разработчиков","ar":"Notion Constraint Memory هو أداة ذكاء اصطناعي تساعد على تحسين إنتاجية المطورين","en":"Being productive is no longer optional"},"seo":{"title":{"zh":"Notion 约束内存 AI 工具","ja":"Notion 制約メモリ AI エージェント","ko":"Notion 제약 메모리 AI 에이전트","es":"Herramientas de IA: Notion Constraint Memory","fr":"Outils d''IA: Notion Constraint Memory","de":"KI-Tools: Notion Constraint Memory","pt":"Ferramentas de IA: Notion Constraint Memory para Desenvol...","ru":"ИИ Агенты: Notion Constraint Memory для Продуктивности","ar":"أدوات الذكاء الاصطناعي: Notion Constraint Memory لزيادة ا...","en":"notion-constraint-memory"},"description":{"zh":"Notion 约束内存 AI 工具旨在提高生产力。通过优化内存使用，开发者可以更高效地工作","ja":"Notion 制約メモリ AI エージェントは、生産性を高めることを目的としています。メモリ使用を最適化することで、開発者はより効率的に作業できます","ko":"Notion 제약 메모리 AI 에이전트는 생산성을 높이는 것을 목표로합니다. 메모리 사용을 최적화함으로써 개발자는 더 효율적으로 작업할 수 있습니다","es":"Notion Constraint Memory es una herramienta de IA que ayuda a mejorar la productividad mediante la optimización de la memoria","fr":"Notion Constraint Memory est un outil d''IA qui aide à améliorer la productivité en optimisant la mémoire","de":"Notion Constraint Memory ist ein KI-Tool, das die Produktivität durch die Optimierung des Speichers verbessert","pt":"O Notion Constraint Memory é uma ferramenta de IA que ajuda a melhorar a produtividade dos desenvolvedores","ru":"Notion Constraint Memory - это инструмент ИИ, который помогает повысить производительность разработчиков","ar":"Notion Constraint Memory هو أداة ذكاء اصطناعي تساعد على تحسين إنتاجية المطورين","en":"Being productive is no longer optional"},"definition":{"en":"Being productive is no longer optional"},"features":{"zh":["优化 Notion 内存使用","提高开发者生产力","支持多种编程语言","提供实时反馈和分析","集成 Notion API","支持 CLI 和 GUI 模式"],"ja":["Notion のメモリ使用を最適化","開発者の生産性を向上させる","複数のプログラミング言語をサポート","リアルタイムのフィードバックと分析を提供","Notion API を統合","CLI と GUI モードをサポート"],"ko":["Notion의 메모리 사용을 최적화","개발자의 생산성을 향상시키는","복수의 프로그래밍 언어를 지원","실시간 피드백과 분석을 제공","Notion API를 통합","CLI와 GUI 모드를 지원"],"es":["Optimización de la memoria para mejorar la productividad","Integración con herramientas de desarrollo como React y Node.js","Compatibilidad con CLI para una mayor flexibilidad","Soporte para múltiples plataformas, incluyendo Python"],"fr":["Optimisation de la mémoire pour améliorer la productivité","Intégration avec des outils de développement tels que React et Node.js","Compatibilité avec CLI pour une plus grande flexibilité","Prise en charge de plusieurs plateformes, notamment Python"],"de":["Optimierung des Speichers, um die Produktivität zu verbessern","Integration mit Entwicklungstools wie React und Node.js","Kompatibilität mit CLI für eine größere Flexibilität","Unterstützung für mehrere Plattformen, einschließlich Python"],"pt":["Otimização da memória para melhorar a produtividade","Integração com ferramentas de desenvolvimento","Suporte a múltiplos ambientes de desenvolvimento","Fácil instalação e configuração","Documentação completa e suporte técnico"],"ru":["Оптимизация памяти для повышения производительности","Интеграция с инструментами разработки","Поддержка нескольких сред разработки","Легкая установка и настройка","Полная документация и техническая поддержка"],"ar":["تحسين الذاكرة لزيادة الإنتاجية","التكامل مع أدوات التطوير","دعم بيئات التطوير المتعددة","تثبيت وتهيئة سهلة","وثائق شاملة ودعم فني"]},"keywords":{"zh":["Notion AI 工具","如何使用 Notion 优化内存","Notion 内存使用优化","Notion 制約内存","Notion 开发者工具","Notion API 集成","Notion CLI 模式","Notion GUI 模式","Notion 生产力工具"],"ja":["Notion AI エージェント","Notion でメモリを最適化する方法","Notion メモリ使用最適化","Notion 制約メモリ","Notion 開発者ツール","Notion API 統合","Notion CLI モード","Notion GUI モード","Notion 生産性ツール"],"ko":["Notion AI 에이전트","Notion에서 메모리를 최적화하는 방법","Notion 메모리 사용 최적화","Notion 제약 메모리","Notion 개발자 툴","Notion API 통합","Notion CLI 모드","Notion GUI 모드","Notion 생산성 툴"],"es":["herramientas de IA","notion constraint memory","productividad","optimización de la memoria","react","node.js","cli","python","guias de instalación","configuración de herramientas de IA"],"fr":["outils d''IA","notion constraint memory","productivité","optimisation de la mémoire","react","node.js","cli","python","guides d''installation","configuration des outils d''IA"],"de":["KI-Tools","notion constraint memory","produktivität","optimierung des speichers","react","node.js","cli","python","installationsanleitungen","konfiguration von KI-Tools"],"pt":["ferramentas de ia para desenvolvedores","notion constraint memory","produtividade para desenvolvedores","otimização da memória","integração com ferramentas de desenvolvimento","guia de instalação do notion constraint memory","alternativas ao notion constraint memory"],"ru":["ИИ Агенты для разработчиков","notion constraint memory","производительность для разработчиков","оптимизация памяти","интеграция с инструментами разработки","руководство по установке notion constraint memory","альтернативы notion constraint memory"],"ar":["أدوات الذكاء الاصطناعي لل개발ين","notion constraint memory","إنتاجية المطورين","تحسين الذاكرة","التكامل مع أدوات التطوير","دليل تثبيت notion constraint memory","بديل ل notion constraint memory"]}},"owner":"hugocool","repo":"FateForger","repoPath":"hugocool/FateForger","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.756Z","topics":[],"category":"community","skillMd":{"name":"notion-constraint-memory","description":"Use the constraint-memory MCP tools to query/upsert timeboxing constraints stored in Notion.","version":"0.1.0","bodyPreview":"Use this skill when working with the timeboxing preference memory stored in Notion.\nDo NOT call Notion APIs directly; use the MCP tools from the constraint-memory server.\n\nTools\n- `constraint_get_store_info()`\n- `constraint_get_constraint(uid)`\n- `constraint_query_types(stage, event_types)`\n- `constraint_query_constraints(filters, type_ids, tags, sort, limit)`\n- `constraint_upsert_constraint(record, event)`\n- `constraint_log_event(event)`\n- `constraint_seed_types()`\n\nServer\n- Script: `scripts/co","body":"Use this skill when working with the timeboxing preference memory stored in Notion.\nDo NOT call Notion APIs directly; use the MCP tools from the constraint-memory server.\n\nTools\n- `constraint_get_store_info()`\n- `constraint_get_constraint(uid)`\n- `constraint_query_types(stage, event_types)`\n- `constraint_query_constraints(filters, type_ids, tags, sort, limit)`\n- `constraint_upsert_constraint(record, event)`\n- `constraint_log_event(event)`\n- `constraint_seed_types()`\n\nServer\n- Script: `scripts/constraint_mcp_server.py`\n- Transport: stdio (recommended)\n\nEnvironment\n- `NOTION_TOKEN`: Notion integration token.\n- `NOTION_TIMEBOXING_PARENT_PAGE_ID`: parent page where the DBs live.\n\nUsage notes\n- Always call `constraint_query_types` before expanding to constraint queries.\n- Use `constraint_upsert_constraint` with an event payload for audit logging when possible.\n"},"lastSynced":"2026-03-04T14:13:55.705Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Claude Code and AutoGPT needing advanced Notion integration and constraint-based memory management.","zh":"适合于需要高级Notion集成和基于约束的内存管理的AI代理，如Claude Code和AutoGPT。","ja":"Claude CodeやAutoGPTのような、Notionの高度な統合と制約ベースのメモリ管理が必要なAIエージェントに最適です。","ko":"Notion의 고급 통합 및 제약 기반 메모리 관리가 필요한 Claude Code 및 AutoGPT와 같은 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA como Claude Code y AutoGPT que necesitan una integración avanzada con Notion y gestión de memoria basada en restricciones.","fr":"Idéal pour les agents IA comme Claude Code et AutoGPT nécessitant une intégration avancée à Notion et une gestion de mémoire basée sur des contraintes.","de":"Ideal für KI-Agents wie Claude Code und AutoGPT, die eine erweiterte Notion-Integration und eine auf Einschränkungen basierende Speicherverwaltung benötigen.","pt":"Ideal para Agentes de IA como Claude Code e AutoGPT que necessitam de integração avançada com o Notion e gerenciamento de memória baseado em restrições.","ru":"Идеально для агентов ИИ, таких как Claude Code и AutoGPT, требующих расширенной интеграции с Notion и управления памятью на основе ограничений.","ar":"مثالي لعميل الذكاء الاصطناعي مثل Claude Code و AutoGPT الذي يحتاج إلى دمج متقدم مع Notion وإدارة الذاكرة القائمة على القيود."},"recommendation":{"en":"Empowers agents to leverage the MCP tools from the constraint-memory server, utilizing functions like `constraint_get_store_info()` and `constraint_upsert_constraint()` to seamlessly interact with Notion, enabling efficient timeboxing preference memory storage and retrieval via protocols like API calls, without directly accessing Notion APIs.","zh":"赋予代理使用来自约束内存服务器的MCP工具的能力，利用诸如`constraint_get_store_info()`和`constraint_upsert_constraint()`之类的函数来与Notion进行无缝交互，实现通过API调用等协议高效地存储和检索时间盒首选项内存，而无需直接访问Notion API。","ja":"制約メモリサーバーのMCPツールを使用するエージェントの能力を付与し、`constraint_get_store_info()`や`constraint_upsert_constraint()`などの関数を使用してNotionとシームレスに相互作用し、API呼び出しなどのプロトコルを介して時間ボックスの優先メモリを効率的にストアおよびリトリーブすることを可能にし、Notion APIに直接アクセスする必要はありません。","ko":"제약 메모리 서버의 MCP 도구를 사용하여 에이전트가 능력을 부여하고, `constraint_get_store_info()` 및 `constraint_upsert_constraint()`와 같은 함수를 사용하여 Notion과 무결점으로 상호 작용하여 API 호출과 같은 프로토콜을 통해 시간 상자首选项 메모리를 효율적으로 저장 및检索 하며, Notion API에 직접 액세스 할 필요가 없습니다.","es":"Habilita a los agentes a aprovechar las herramientas MCP desde el servidor de memoria de restricciones, utilizando funciones como `constraint_get_store_info()` y `constraint_upsert_constraint()` para interactuar de forma transparente con Notion, lo que permite un almacenamiento y recuperación eficientes de la memoria de preferencias de timeboxing a través de protocolos como llamadas a la API, sin acceder directamente a las API de Notion.","fr":"Permet aux agents d''utiliser les outils MCP à partir du serveur de mémoire de contraintes, en utilisant des fonctions comme `constraint_get_store_info()` et `constraint_upsert_constraint()` pour interagir de manière transparente avec Notion, ce qui permet un stockage et une récupération efficaces de la mémoire de préférences de timeboxing via des protocoles comme des appels d''API, sans accéder directement aux API Notion.","de":"Ermöglicht es Agents, die MCP-Tools vom Constraint-Memory-Server zu nutzen, indem Funktionen wie `constraint_get_store_info()` und `constraint_upsert_constraint()` verwendet werden, um nahtlos mit Notion zu interagieren, was einen effizienten Speicher und Abruf von Timeboxing-Präferenzspeicher über Protokolle wie API-Aufrufe ermöglicht, ohne direkt auf Notion-APIs zuzugreifen.","pt":"Permite que os agentes utilizem as ferramentas MCP do servidor de memória de restrição, utilizando funções como `constraint_get_store_info()` e `constraint_upsert_constraint()` para interagir sem problemas com o Notion, permitindo o armazenamento e recuperação eficientes de preferências de timeboxing via protocolos como chamadas de API, sem acessar diretamente as APIs do Notion.","ru":"Позволяет агентам использовать инструменты MCP сервера памяти ограничений, используя функции как `constraint_get_store_info()` и `constraint_upsert_constraint()`, для бесшовного взаимодействия с Notion, обеспечивая эффективное хранение и получение предпочтений timeboxing через протоколы, такие как вызовы API, без прямого доступа к API Notion.","ar":"تمكّن الوكلاء من استخدام أدوات MCP من خادم الذاكرة القائم على القيود، باستخدام وظائف مثل `constraint_get_store_info()` و `constraint_upsert_constraint()` للتفاعل بسلاسة مع Notion، وتمكين تخزين واسترجاع كفء لتفضيلات timeboxing عبر بروتوكولات مثل呼び出し API، دون الوصول المباشر إلى APIs Notion."},"useCases":{"en":["Automating timeboxing preference updates in Notion using `constraint_upsert_constraint()`","Querying constraint types and filters with `constraint_query_types()` and `constraint_query_constraints()`","Logging events with `constraint_log_event()` for comprehensive memory tracking"],"zh":["使用`constraint_upsert_constraint()`自动在Notion中更新时间盒首选项","使用`constraint_query_types()`和`constraint_query_constraints()`查询约束类型和过滤器","使用`constraint_log_event()`记录事件以进行全面内存跟踪"],"ja":["時間ボックスの優先設定をNotionで自動更新するために`constraint_upsert_constraint()`を使用する","`constraint_query_types()`および`constraint_query_constraints()`を使用して制約タイプとフィルタを照会する","全面的メモリ追跡のために`constraint_log_event()`を使用してイベントをログする"],"ko":["Notion에서 시간 상자首选项을 자동으로 업데이트하려면 `constraint_upsert_constraint()`을 사용하십시오.","`constraint_query_types()` 및 `constraint_query_constraints()`를 사용하여 제약 유형 및 필터를 쿼리합니다.","포괄적인 메모리 추적을 위해 `constraint_log_event()`를 사용하여 이벤트를 기록합니다."],"es":["Automatizar actualizaciones de preferencias de timeboxing en Notion utilizando `constraint_upsert_constraint()`","Consultar tipos y filtros de restricciones con `constraint_query_types()` y `constraint_query_constraints()`","Registrar eventos con `constraint_log_event()` para un seguimiento de memoria integral"],"fr":["Automatiser les mises à jour des préférences de timeboxing dans Notion en utilisant `constraint_upsert_constraint()`","Interroger les types et les filtres de contraintes avec `constraint_query_types()` et `constraint_query_constraints()`","Enregistrer des événements avec `constraint_log_event()` pour un suivi de mémoire complet"],"de":["Automatisieren von Timeboxing-Präferenzaktualisierungen in Notion mit `constraint_upsert_constraint()`","Abfragen von Einschränkungstypen und -filtern mit `constraint_query_types()` und `constraint_query_constraints()`","Ereignisse mit `constraint_log_event()` für eine umfassende Speicherüberwachung protokollieren"],"pt":["Automatizar atualizações de preferências de timeboxing no Notion usando `constraint_upsert_constraint()`","Consultar tipos de restrição e filtros com `constraint_query_types()` e `constraint_query_constraints()`","Registrar eventos com `constraint_log_event()` para acompanhamento abrangente da memória"],"ru":["Автоматизировать обновления предпочтений timeboxing в Notion, используя `constraint_upsert_constraint()`","Запрашивать типы ограничений и фильтры с помощью `constraint_query_types()` и `constraint_query_constraints()`","Регистрировать события с помощью `constraint_log_event()` для всестороннего отслеживания памяти"],"ar":["توفير تحديثات تلقائية لتفضيلات timeboxing في Notion باستخدام `constraint_upsert_constraint()`","استعلام أنواع القيود والمرشحات باستخدام `constraint_query_types()` و `constraint_query_constraints()`","تسجيل الأحداث باستخدام `constraint_log_event()` لتتبع شاملا للذاكرة"]},"limitations":{"en":["Requires access to the constraint-memory server and its MCP tools","Must use provided functions and not directly call Notion APIs"],"zh":["需要访问约束内存服务器及其MCP工具","必须使用提供的函数，而不是直接调用Notion API"],"ja":["制約メモリサーバー及其のMCPツールへのアクセスが必要です","Notion APIを直接呼び出すのではなく、提供された関数を使用する必要があります"],"ko":["제약 메모리 서버 및 해당 MCP 도구에 액세스해야 합니다.","Notion API를 직접 호출하는 대신 제공된 함수를 사용해야 합니다."],"es":["Requiere acceso al servidor de memoria de restricciones y a sus herramientas MCP","Debe utilizar las funciones proporcionadas y no llamar directamente a las API de Notion"],"fr":["Nécessite un accès au serveur de mémoire de contraintes et à ses outils MCP","Doit utiliser les fonctions fournies et non appeler directement les API Notion"],"de":["Erfordert Zugriff auf den Constraint-Memory-Server und seine MCP-Tools","Muss die bereitgestellten Funktionen verwenden und darf nicht direkt auf Notion-APIs zugreifen"],"pt":["Requer acesso ao servidor de memória de restrição e às suas ferramentas MCP","Deve usar funções fornecidas e não chamar diretamente as APIs do Notion"],"ru":["Требует доступа к серверу памяти ограничений и его инструментам MCP","Должен использовать предоставленные функции и не вызывать напрямую API Notion"],"ar":["يتطلب الوصول إلى خادم الذاكرة القائم على القيود وأدواته MCP","يجب استخدام الوظائف الموفّرة ولا يتم الوصول المباشر إلى APIs Notion"]},"version":3},"contentHash":"f184cbce2535c2be1594c71643aa4e8307087da4ee40cc44c793c5118eaae42e","qualityScore":26}');
