INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anabelle/acars.pub/nostr', 'nostr', 'anabelle', 'acars.pub', 'community', 'nostr anabelle acars.pub community nostr是一个基于NOSTR的航空公司模拟器，提供了一个新的体验方式 nostrはNOSTRを基盤とした航空会社シミュレーターであり、新しい体験方法を提供します nostr은 NOSTR 기반의 항공사 시뮬레이터로 새로운 경험 방식을 제공합니다 El simulador de aerolíneas sobre nostr permite a los desarrolladores crear experiencias de vuelo realistas con agentes de inteligencia artificial Le simulateur de compagnies aériennes sur nostr permet aux développeurs de créer des expériences de vol réalistes avec des outils d''IA Der Fluggesellschaften-Simulator über nostr ermöglicht es Entwicklern, realistische Flugerfahrungen mit KI-Agenten zu erstellen O simulador de companhias aéreas com NOSTR é uma ferramenta de IA que ajuda no desenvolvimento de soluções para a indústria aérea Симулятор авиакомпаний с NOSTR - это инструмент ИИ, помогающий в разработке решений для авиаиндустрии محاكي شركات الطيران مع NOSTR هو أداة ذكاء اصطناعي تساعد في تطوير حلول للصناعة الجوية Airlines Simulator over NOSTR nostr AI工具 航空公司模拟 NOSTR AI智能工具 如何使用nostr nostr与其他工具的比较 nostr安装指南 nostr设置教程 Airlines Simulator over NOSTR');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('svetzal/researcher-cli/deploy-skills', 'community', 'svetzal', 'researcher-cli', 'svetzal/researcher-cli', 'deploy-skills', 0, 0, 25, '2026-03-03T12:40:14Z', '2026-03-03T15:19:30.348Z', '7def1c617a1fe8f3adc40d76a3e0072ec48b666f2a25a44a6ddaca1e08743998', '{"id":"svetzal/researcher-cli/deploy-skills","name":"deploy-skills","description":{"zh":"deploy-skills是一款CLI工具，用于索引和搜索文档仓库，帮助开发者提高效率","ja":"deploy-skillsは、ドキュメントリポジトリのインデックスと検索を支援するCLIツールです","ko":"deploy-skills는 문서 저장소의 색인 및 검색을 지원하는 CLI 도구입니다","es":"Deploy-skills es una herramienta de línea de comandos para indexar y buscar documentos en repositorios de forma eficiente","fr":"Deploy-skills est un outil en ligne de commande pour indexer et rechercher des documents dans les référentiels de manière efficace","de":"Deploy-skills ist ein CLI-Tool zum Indizieren und Suchen von Dokumenten in Repositorien auf effiziente Weise","pt":"O deploy-skills é uma ferramenta de linha de comando para indexação e busca de repositórios de documentos","ru":"Deploy-skills - это CLI инструмент для индексации и поиска документов в репозиториях","ar":"deploy-skills هي أداة سطر أوامر للفهرسة والبحث في مستودعات الوثائق","en":"CLI tool for indexing and searching document repositories"},"seo":{"title":{"zh":"AI智能工具：deploy-skills 文档仓库索引和搜索","ja":"AIエージェント：deploy-skills ドキュメントリポジトリのインデックスと検索","ko":"AI 에이전트: deploy-skills 문서 저장소 색인 및 검색","es":"Herramientas de IA: deploy-skills para búsqueda de docume...","fr":"Outils IA: deploy-skills pour la recherche de documents","de":"KI-Tools: deploy-skills für die Suche in Dokumentenreposi...","pt":"Ferramenta de Indexação de Repositórios de Documentos - d...","ru":"ИИ Агенты: Индексация и Поиск Документов с deploy-skills","ar":"أداة إدارة مستودعات الوثائق - deploy-skills","en":"deploy-skills"},"description":{"zh":"deploy-skills是一款CLI工具，用于索引和搜索文档仓库，帮助开发者提高效率","ja":"deploy-skillsは、ドキュメントリポジトリのインデックスと検索を支援するCLIツールです","ko":"deploy-skills는 문서 저장소의 색인 및 검색을 지원하는 CLI 도구입니다","es":"Deploy-skills es una herramienta de línea de comandos para indexar y buscar documentos en repositorios de forma eficiente","fr":"Deploy-skills est un outil en ligne de commande pour indexer et rechercher des documents dans les référentiels de manière efficace","de":"Deploy-skills ist ein CLI-Tool zum Indizieren und Suchen von Dokumenten in Repositorien auf effiziente Weise","pt":"O deploy-skills é uma ferramenta de linha de comando para indexação e busca de repositórios de documentos","ru":"Deploy-skills - это CLI инструмент для индексации и поиска документов в репозиториях","ar":"deploy-skills هي أداة سطر أوامر للفهرسة والبحث في مستودعات الوثائق","en":"CLI tool for indexing and searching document repositories"},"definition":{"en":"CLI tool for indexing and searching document repositories"},"features":{"zh":["支持文档仓库的索引和搜索","提供CLI工具便于开发者使用","提高开发效率和生产力","支持多种文档格式","易于安装和配置"],"ja":["ドキュメントリポジトリのインデックスと検索をサポート","CLIツールを提供して開発者が使用しやすくする","開発効率と生産性を向上させる","複数のドキュメント形式をサポート","簡単にインストールと設定が可能"],"ko":["문서 저장소의 색인 및 검색을 지원","CLI 도구를 제공하여 개발자가 사용하기 쉽게 함","개발 효율성과 생산성을 향상","여러 문서 형식을 지원","쉽게 설치 및 설정 가능"],"es":["Indexación de documentos","Búsqueda en repositorios","Interfaz de línea de comandos","Compatibilidad con múltiples formatos de documentos","Búsqueda eficiente y precisa"],"fr":["Indexation de documents","Recherche dans les référentiels","Interface en ligne de commande","Compatibilité avec plusieurs formats de documents","Recherche efficace et précise"],"de":["Indizierung von Dokumenten","Suche in Repositorien","CLI-Schnittstelle","Kompatibilität mit mehreren Dokumentenformaten","Effiziente und präzise Suche"],"pt":["Indexação de repositórios de documentos","Busca eficiente de documentos","Ferramenta de linha de comando (CLI)","Integração com tecnologias de desenvolvimento","Suporte a vários formatos de documentos"],"ru":["Индексация репозиториев документов","Эффективный поиск документов","Инструмент командной строки (CLI)","Интеграция с технологиями разработки","Поддержка нескольких форматов документов"],"ar":["فهرسة مستودعات الوثائق","بحث فعال للوثائق","أداة سطر أوامر (CLI)","التكامل مع تقنيات التطوير","دعم عدة صيغ للوثائق"]},"keywords":{"zh":["如何使用deploy-skills","什么是deploy-skills","deploy-skills替代品","deploy-skills vs 其他工具","deploy-skills安装","deploy-skills设置指南","CLI工具","文档仓库索引","文档仓库搜索"],"ja":["deploy-skillsの使い方","deploy-skillsとは","deploy-skillsの代替","deploy-skills vs 他のツール","deploy-skillsのインストール","deploy-skillsの設定ガイド","CLIツール","ドキュメントリポジトリのインデックス","ドキュメントリポジトリの検索"],"ko":["deploy-skills 사용 방법","deploy-skills란","deploy-skills 대체","deploy-skills vs 다른 도구","deploy-skills 설치","deploy-skills 설정 가이드","CLI 도구","문서 저장소 색인","문서 저장소 검색"],"es":["cómo usar deploy-skills","qué es deploy-skills","alternativas a deploy-skills","deploy-skills vs elastic search","instalación de deploy-skills","guía de configuración de deploy-skills","búsqueda de documentos en línea","herramientas de IA para la búsqueda de documentos"],"fr":["comment utiliser deploy-skills","qu''est-ce que deploy-skills","alternatives à deploy-skills","deploy-skills vs elastic search","installation de deploy-skills","guide de configuration de deploy-skills","recherche de documents en ligne","outils d''IA pour la recherche de documents"],"de":["wie man deploy-skills verwendet","was ist deploy-skills","alternativen zu deploy-skills","deploy-skills vs elastic search","installation von deploy-skills","konfigurationsanleitung für deploy-skills","suche nach dokumenten online","KI-tools für die suche nach dokumenten"],"pt":["como usar deploy-skills","o que é deploy-skills","deploy-skills alternativa","deploy-skills vs elastic search","instalar deploy-skills","guia de configuração do deploy-skills"],"ru":["как использовать deploy-skills","что такое deploy-skills","deploy-skills альтернатива","deploy-skills vs elastic search","установить deploy-skills","руководство по настройке deploy-skills"],"ar":["كيفية استخدام deploy-skills","ما هو deploy-skills","بديل deploy-skills","deploy-skills مقابل elastic search","تثبيت deploy-skills","دليل إعداد deploy-skills"]}},"owner":"svetzal","repo":"researcher-cli","repoPath":"svetzal/researcher-cli","stars":0,"forks":0,"updatedAt":"2026-03-03T12:40:14Z","topics":[],"category":"community","skillMd":{"name":"deploy-skills","description":"Deploy this projects skills/ folder to global skill locations; use when the user asks to deploy, publish, sync, or push skills to Claude or Openclaw","bodyPreview":"# Deploy Skills\n\nCopy skills from this project''s `skills/` folder into the global skill locations so they are available in all sessions.\n\n## Target Locations\n\n| Agent | Global Skills Path |\n|-------|-------------------|\n| Claude Code | `~/.claude/skills/` |\n| Openclaw | `~/.openclaw/workspace/skills/` |\n\n## Workflow\n\n### 1. Identify skills to deploy\n\nList the project''s skills:\n\n```bash\nls skills/\n```\n\nEach subdirectory is a skill to deploy.\n\n### 2. Diff each skill against both targets\n\nFor each","body":"# Deploy Skills\n\nCopy skills from this project''s `skills/` folder into the global skill locations so they are available in all sessions.\n\n## Target Locations\n\n| Agent | Global Skills Path |\n|-------|-------------------|\n| Claude Code | `~/.claude/skills/` |\n| Openclaw | `~/.openclaw/workspace/skills/` |\n\n## Workflow\n\n### 1. Identify skills to deploy\n\nList the project''s skills:\n\n```bash\nls skills/\n```\n\nEach subdirectory is a skill to deploy.\n\n### 2. Diff each skill against both targets\n\nFor each skill directory, check whether it differs from the installed versions:\n\n```bash\ndiff -r skills/<name> ~/.claude/skills/<name>\ndiff -r skills/<name> ~/.openclaw/workspace/skills/<name>\n```\n\n### 3. Copy changed skills\n\nFor any skill that differs (or doesn''t exist at the target), copy it:\n\n```bash\ncp -r skills/<name> ~/.claude/skills/\ncp -r skills/<name> ~/.openclaw/workspace/skills/\n```\n\n### 4. Report results\n\nTell the user which skills were updated and which were already up to date.\n\n## Rules\n\n- **Only copy from `skills/` → global locations.** Never copy in the reverse direction.\n- **Never touch skills in the global locations that don''t exist in this project''s `skills/` folder.** Other projects own those.\n- **Do not create skills at the target if the source skill directory is empty or malformed** (missing `SKILL.md`).\n- Copying is non-destructive: `cp -r` overwrites but does not delete unrelated skills at the target.\n"},"lastSynced":"2026-03-03T15:19:30.348Z","agentAnalysis":{"suitability":{"en":"Perfect for CLI-based AI Agents needing skill deployment and management across multiple sessions.","zh":"适合需要跨多个会话部署和管理技能的基于CLI的AI代理。","ja":"CLIベースのAIエージェントが複数のセッションでスキルを展開および管理する必要がある場合に適しています。","ko":"다중 세션에서 스킬을 배포 및 관리해야 하는 CLI 기반 AI 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA basados en CLI que necesitan implementación y administración de habilidades en varias sesiones.","fr":"Parfait pour les agents d''IA basés sur CLI nécessitant le déploiement et la gestion de compétences sur plusieurs sessions.","de":"Perfekt für CLI-basierte KI-Agents, die die Bereitstellung und Verwaltung von Fähigkeiten über mehrere Sitzungen hinweg benötigen.","pt":"Perfeito para Agentes de IA baseados em CLI que precisam de implantação e gerenciamento de habilidades em várias sessões.","ru":"Идеально подходит для агентов ИИ на основе CLI, которым необходимы развертывание и управление навыками в нескольких сессиях.","ar":"مثالي لعميل الذكاء الاصطناعي الذي يعتمد على CLI والذي يحتاج إلى نشر وإدارة المهارات عبر عدة جلسات."},"recommendation":{"en":"Empowers agents to seamlessly copy skills into global locations, leveraging CLI tools for indexing and searching document repositories, and supporting agents like Claude Code and Openclaw with targeted global skills paths such as ~/.claude/skills/ and ~/.openclaw/workspace/skills/.","zh":"赋予代理无缝地将技能复制到全局位置，利用CLI工具对文档存储库进行索引和搜索，并支持具有特定全局技能路径（如~/.claude/skills/和~/.openclaw/workspace/skills/）的代理，如Claude Code和Openclaw。","ja":"エージェントがスキルをグローバルロケーションにシームレスにコピーできるようにし、CLIツールを使用してドキュメントリポジトリをインデックスして検索し、Claude CodeやOpenclawなどのエージェント（〜/.claude/skills/や〜/.openclaw/workspace/skills/など）をサポートします。","ko":"에이전트가 Claude Code와 Openclaw와 같은 에이전트를 대상으로 하여 글로벌 스킬 경로(~/.claude/skills/ 및 ~/.openclaw/workspace/skills/)와 같은 글로벌 위치에 스킬을 무중단으로 복사할 수 있도록 하며 CLI 도구를 사용하여 문서 저장소를 색인하고 검색합니다.","es":"Habilita a los agentes a copiar habilidades de forma transparente en ubicaciones globales, aprovechando herramientas de CLI para indexar y buscar repositorios de documentos, y soportando agentes como Claude Code y Openclaw con rutas de habilidades globales dirigidas como ~/.claude/skills/ y ~/.openclaw/workspace/skills/.","fr":"Permet aux agents de copier des compétences de manière transparente dans des emplacements globaux, en exploitant les outils de ligne de commande pour indexer et rechercher des référentiels de documents, et en prenant en charge des agents comme Claude Code et Openclaw avec des chemins de compétences globales ciblés tels que ~/.claude/skills/ et ~/.openclaw/workspace/skills/.","de":"Ermöglicht es Agents, Fähigkeiten nahtlos in globale Standorte zu kopieren, indem CLI-Tools für die Indizierung und Suche in Dokumenten-Repositorys genutzt werden, und unterstützt Agents wie Claude Code und Openclaw mit gezielten globalen Fähigkeitspfaden wie ~/.claude/skills/ und ~/.openclaw/workspace/skills/.","pt":"Habilita os agentes a copiar habilidades para locais globais de forma transparente, utilizando ferramentas CLI para indexação e pesquisa de repositórios de documentos, e suporta agentes como Claude Code e Openclaw com caminhos de habilidades globais direcionados, como ~/.claude/skills/ e ~/.openclaw/workspace/skills/.","ru":"Наделяет агентов возможностью бесшовного копирования навыков в глобальные местоположения, используя инструменты CLI для индексации и поиска репозиториев документов, и поддерживает агентов, такие как Claude Code и Openclaw, с нацеленными глобальными путями навыков, такими как ~/.claude/skills/ и ~/.openclaw/workspace/skills/.","ar":"يمكن للعميل نسخ المهارات إلى مواقع عالمية بسهولة، باستخدام أدوات CLI لفهرسة و البحث عن مستودعات الوثائق، ودعم العملاء مثل Claude Code و Openclaw مع مسارات مهارات عالمية محددة مثل ~/.claude/skills/ و ~/.openclaw/workspace/skills/."},"useCases":{"en":["Deploying custom skills across multiple agent sessions","Managing global skill locations for consistent agent behavior","Streamlining skill development with automated deployment scripts"],"zh":["跨多个代理会话部署自定义技能","管理全局技能位置以实现一致的代理行为","使用自动化部署脚本简化技能开发"],"ja":["カスタムスキルを複数のエージェントセッションに展開する","エージェントの動作を一貫性を持たせるためのグローバルスキルロケーションの管理","自動化された展開スクリプトを使用してスキル開発を簡素化する"],"ko":["다중 에이전트 세션에서 사용자 정의 스킬을 배포하는 것","일관된 에이전트 동작을 위한 글로벌 스킬 위치 관리","자동화된 배포 스크립트를 사용하여 스킬 개발을 간소화하는 것"],"es":["Implementar habilidades personalizadas en varias sesiones de agente","Administrar ubicaciones de habilidades globales para un comportamiento de agente coherente","Optimizar el desarrollo de habilidades con scripts de implementación automatizados"],"fr":["Déployer des compétences personnalisées sur plusieurs sessions d''agent","Gérer des emplacements de compétences globales pour un comportement d''agent cohérent","Optimiser le développement de compétences avec des scripts de déploiement automatisés"],"de":["Bereitstellen von benutzerdefinierten Fähigkeiten über mehrere Agentensitzungen hinweg","Verwalten globaler Fähigkeitsstandorte für ein konsistentes Agentenverhalten","Optimieren der Fähigkeitsentwicklung mit automatisierten Bereitstellungsskripten"],"pt":["Implantar habilidades personalizadas em várias sessões de agente","Gerenciar locais de habilidades globais para comportamento de agente consistente","Otimizar o desenvolvimento de habilidades com scripts de implantação automatizados"],"ru":["Развертывание пользовательских навыков в нескольких сессиях агента","Управление глобальными местоположениями навыков для последовательного поведения агента","Оптимизация разработки навыков с помощью автоматизированных скриптов развертывания"],"ar":["نشر مهارات مخصصة عبر عدة جلسات للعميل","إدارة مواقع المهارات العالمية للتصرف الموحد للعميل","تعزيز تطوير المهارات باستخدام سكريبتات نشر آلي"]},"limitations":{"en":["Requires filesystem access and write permissions","Limited to supported agents with defined global skills paths","Dependent on CLI tool functionality for skill indexing and searching"],"zh":["需要文件系统访问和写入权限","仅限于具有定义的全局技能路径的支持代理","依赖于CLI工具的功能来进行技能索引和搜索"],"ja":["ファイルシステムへのアクセスと書き込み権限が必要","グローバルスキルパスが定義されたサポート対象エージェントのみ","スキル索引と検索のためのCLIツールの機能に依存"],"ko":["파일 시스템 액세스 및 쓰기 권한이 필요","정의된 글로벌 스킬 경로를 갖는 지원 에이전트에만 제한","스킬 색인 및 검색을 위한 CLI 도구 기능에 의존"],"es":["Requiere acceso al sistema de archivos y permisos de escritura","Limitado a agentes compatibles con rutas de habilidades globales definidas","Dependiente de la funcionalidad de las herramientas de CLI para la indexación y búsqueda de habilidades"],"fr":["Nécessite un accès au système de fichiers et des autorisations d''écriture","Limité aux agents pris en charge avec des chemins de compétences globales définis","Dépend de la fonctionnalité des outils de ligne de commande pour l''indexation et la recherche de compétences"],"de":["Benötigt Dateisystemzugriff und Schreibberechtigungen","Begrenzt auf unterstützte Agents mit definierten globalen Fähigkeitspfaden","Abhängig von der Funktionalität von CLI-Tools für die Indizierung und Suche von Fähigkeiten"],"pt":["Requer acesso ao sistema de arquivos e permissões de gravação","Limitado a agentes suportados com caminhos de habilidades globais definidos","Dependente da funcionalidade da ferramenta CLI para indexação e pesquisa de habilidades"],"ru":["Требует доступа к файловой системе и разрешений на запись","Ограничен агентами с определенными глобальными путями навыков","Зависит от функциональности инструмента CLI для индексации и поиска навыков"],"ar":["يتطلب الوصول إلى نظام الملفات و صلاحيات الكتابة","محدود بالعملاء المدعومين الذين لديهم مسارات مهارات عالمية محددة","يعتمد على أداة CLI لفهرسة و البحث عن المهارات"]},"version":3},"contentHash":"7def1c617a1fe8f3adc40d76a3e0072ec48b666f2a25a44a6ddaca1e08743998","qualityScore":25}');
