INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('optimistic-updt/sync-agents/implement-plan', 'implement-plan', 'optimistic-updt', 'sync-agents', 'community', 'implement-plan optimistic-updt sync-agents community 实现计划是AI智能体的核心功能，Sync Agent 脚本和基本工作流可以帮助您提高开发效率 実装計画はAIエージェントの重要な機能であり、Sync Agent スクリプトと基本ワークフローを使用して開発効率を向上させることができます 구현 계획은 AI 에이전트의 핵심 기능으로, Sync 에이전트 스크립트와 기본 워크플로를 사용하여 개발 효율성을 높일 수 있습니다 Implementa planes con scripts de agentes y flujos de trabajo básicos para desarrolladores Mettez en œuvre des plans avec des scripts d''agents et des flux de travail de base pour les développeurs Umsetzen Sie Pläne mit Agenten-Skripten und grundlegenden Workflows für Entwickler O implement-plan é uma habilidade que permite sincronizar scripts de agentes e fluxos de trabalho básicos com as Ferramentas de AI Agents. Реализация плана - это навык, который позволяет синхронизировать скрипты агентов и базовые рабочие процессы с ИИ Агентами. تنفيذ الخطة هو مهارة تسمح بمزامنة سكريبتات الوكلاء والعمليات الأساسية مع أدوات الإيجاد الذكي. Sync agent script and basic workflow AI智能体 实现计划 Sync Agent 脚本 基本工作流 自动化开发任务 提高开发效率 优化工作流 AI智能体实战 开发工作流自动化 Sync agent script and basic workflow ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('akiojin/llmlb/hotfix', 'community', 'akiojin', 'llmlb', 'akiojin/llmlb', 'hotfix', 2, 0, 25, '2026-02-28T09:28:07Z', '2026-02-28T12:52:51.154Z', '17cc1b01e20874dbb0a36060132e269a2dd4fd5942479d6c82754edcba26ff86', '{"id":"akiojin/llmlb/hotfix","name":"hotfix","description":{"zh":"hotfix是一种分布式LLM路由器，具有负载均衡和自动模型分布功能，用于提升AI应用的性能和可靠性","ja":"hotfixは分散型LLMルーターで、負荷分散と自動モデル配布機能を備え、AIアプリケーションのパフォーマンスと信頼性を向上","ko":"hotfix는 분산형 LLM 라우터로 로드 밸런싱과 자동 모델 분배 기능을 제공하여 AI 애플리케이션의 성능과 신뢰성을 높여줍니다","es":"hotfix es un enrutador LLM distribuido que ofrece equilibrio de carga y distribución automática de modelos para mejorar el rendimiento","fr":"hotfix est un routeur LLM distribué qui propose un équilibrage de charge et une distribution automatique de modèles pour améliorer les performances","de":"hotfix ist ein verteilter LLM-Verteiler, der Lastenausgleich und automatische Modellverteilung für eine bessere Leistung bietet","pt":"O hotfix é um router LLM distribuído de alto desempenho que fornece balanceamento de carga automático e distribuição inteligente de modelos entre múltiplos endpoints. Ideal para aplicações em produção que exigem escalabilidade e resiliência.","ru":"hotfix — это высокопроизводительный распределенный LLM роутер, обеспечивающий автоматическую балансировку нагрузки и интеллектуальное распределение моделей между несколькими конечными точками. Идеален для production-приложений, требующих масштабируемости и отказоустойчивости.","ar":"hotfix هو موزع LLM موزع عالي الأداء يوفر موازنة حمل تلقائية وتوزيعًا ذكيًا للنماذج بين نقاط نهاية متعددة. مثالي للتطبيقات في بيئة الإنتاج التي تتطلب قابلية التوسع والمرونة.","en":"Distributed LLM router with load balancing and automatic model distribution"},"seo":{"title":{"zh":"AI智能代理hotfix：分布式LLM路由器","ja":"AIエージェントhotfix：分散型LLMルーター","ko":"AI 에이전트 hotfix: 분산형 LLM 라우터","es":"Herramientas de AI: hotfix para enrutamiento LLM","fr":"Outils d''IA : hotfix pour routage LLM","de":"KI-Tools: Hotfix für LLM-Verteiler","pt":"hotfix: Router LLM Distribuído com Load Balancing | Ferra...","ru":"hotfix: Распределенный LLM Роутер с Балансировкой | ИИ Аг...","ar":"hotfix: موزع LLM الموزع مع موازنة الحمل | أدوات الذكاء ال...","en":"hotfix"},"description":{"zh":"hotfix是一种分布式LLM路由器，具有负载均衡和自动模型分布功能，用于提升AI应用的性能和可靠性","ja":"hotfixは分散型LLMルーターで、負荷分散と自動モデル配布機能を備え、AIアプリケーションのパフォーマンスと信頼性を向上","ko":"hotfix는 분산형 LLM 라우터로 로드 밸런싱과 자동 모델 분배 기능을 제공하여 AI 애플리케이션의 성능과 신뢰성을 높여줍니다","es":"hotfix es un enrutador LLM distribuido que ofrece equilibrio de carga y distribución automática de modelos para mejorar el rendimiento","fr":"hotfix est un routeur LLM distribué qui propose un équilibrage de charge et une distribution automatique de modèles pour améliorer les performances","de":"hotfix ist ein verteilter LLM-Verteiler, der Lastenausgleich und automatische Modellverteilung für eine bessere Leistung bietet","pt":"O hotfix é um router LLM distribuído de alto desempenho que fornece balanceamento de carga automático e distribuição inteligente de modelos entre múltiplos e...","ru":"hotfix — это высокопроизводительный распределенный LLM роутер, обеспечивающий автоматическую балансировку нагрузки и интеллектуальное распределение моделей м...","ar":"hotfix هو موزع LLM موزع عالي الأداء يوفر موازنة حمل تلقائية وتوزيعًا ذكيًا للنماذج بين نقاط نهاية متعددة. مثالي للتطبيقات في بيئة الإنتاج التي تتطلب قابلية ا...","en":"Distributed LLM router with load balancing and automatic model distribution"},"definition":{"en":"Distributed LLM router with load balancing and automatic model distribution"},"features":{"zh":["分布式LLM路由","负载均衡","自动模型分布","高性能","高可靠性","易于集成"],"ja":["分散型LLMルーティング","負荷分散","自動モデル配布","高パフォーマンス","高信頼性","容易な統合"],"ko":["분산형 LLM 라우팅","로드 밸런싱","자동 모델 분배","고성능","고신뢰성","쉬운 통합"],"es":["Enrutamiento LLM distribuido","Equilibrio de carga automático","Distribución automática de modelos","Mejora del rendimiento","Escalabilidad horizontal"],"fr":["Routage LLM distribué","Équilibrage de charge automatique","Distribution automatique de modèles","Amélioration des performances","Évolutivité horizontale"],"de":["Verteilte LLM-Verteiler","Automatischer Lastenausgleich","Automatische Modellverteilung","Leistungsverbesserung","Horizontale Skalierbarkeit"],"pt":["Balanceamento de carga automático entre múltiplos endpoints de LLM","Distribuição inteligente de modelos baseada em custo, latência e desempenho","Arquitetura distribuída para alta disponibilidade e escalabilidade","Failover automático em caso de falha de endpoint","Fácil integração com APIs existentes (OpenAI, Anthropic, etc.)","Monitoramento em tempo real e métricas de desempenho"],"ru":["Автоматическая балансировка нагрузки между несколькими LLM конечными точками","Интеллектуальное распределение моделей на основе стоимости, задержки и производительности","Распределенная архитектура для высокой доступности и масштабируемости","Автоматический переход на резервный сервер при сбое конечной точки","Простая интеграция с существующими API (OpenAI, Anthropic и др.)","Мониторинг и метрики производительности в реальном времени"],"ar":["موازنة حمل تلقائية بين نقاط نهاية LLM متعددة","توزيع ذكي للنماذج يعتمد على التكلفة وزمن الوصول والأداء","هندسة معمارية موزعة لتوافر عالٍ وقابلية التوسع","تبديل تلقائي عند فشل نقطة النهاية","تكامل سهل مع واجهات برمجة التطبيقات الحالية (OpenAI, Anthropic, إلخ)","مراقبة في الوقت الفعلي ومقاييس الأداء"]},"keywords":{"zh":["如何使用hotfix","什么是LLM路由器","hotfix替代品","hotfix与其他AI工具的比较","hotfix安装","hotfix设置指南","AI智能代理","分布式LLM路由"],"ja":["hotfixの使い方","LLMルーターの意味","hotfixの代替","hotfixと他のAIツールの比較","hotfixのインストール","hotfixの設定ガイド","AIエージェント","分散型LLMルーティング"],"ko":["hotfix 사용 방법","LLM 라우터의 의미","hotfix 대안","hotfix와 다른 AI 도구의 비교","hotfix 설치","hotfix 설정 가이드","AI 에이전트","분산형 LLM 라우팅"],"es":["herramientas de AI","enrutamiento LLM","equilibrio de carga","distribución de modelos","hotfix alternativa","hotfix vs otros enrutadores","cómo usar hotfix","guía de instalación de hotfix","configuración de hotfix"],"fr":["outils d''IA","routage LLM","équilibrage de charge","distribution de modèles","alternative à hotfix","hotfix vs autres routeurs","comment utiliser hotfix","guide d''installation de hotfix","configuration de hotfix"],"de":["KI-Tools","LLM-Verteiler","Lastenausgleich","Modellverteilung","Hotfix-Alternative","Hotfix vs andere Verteiler","wie man Hotfix verwendet","Installationsanleitung für Hotfix","Hotfix-Konfiguration"],"pt":["router LLM distribuído","balanceamento de carga AI","como usar hotfix","hotfix vs langchain","instalar hotfix CLI","ferramentas IA para desenvolvedores","distribuição automática de modelos","high availability LLM","hotfix setup guide"],"ru":["распределенный LLM роутер","балансировка нагрузки ИИ","как использовать hotfix","hotfix vs langchain","установка hotfix CLI","ИИ агенты для разработчиков","автоматическое распределение моделей","высокая доступность LLM","руководство по настройке hotfix"],"ar":["موزع LLM الموزع","موازنة حمل الذكاء الاصطناعي","كيفية استخدام hotfix","hotfix مقابل langchain","تثبيت hotfix CLI","أدوات الذكاء الاصطناعي للمطورين","توزيع تلقائي للنماذج","توافر عالٍ لـ LLM","دليل إعداد hotfix"]}},"owner":"akiojin","repo":"llmlb","repoPath":"akiojin/llmlb","stars":2,"forks":0,"updatedAt":"2026-02-28T09:28:07Z","topics":[],"category":"community","skillMd":{"name":"hotfix","description":"Execute the hotfix workflow when the user asks `hotfix` or `/hotfix`: create a hotfix branch from main, guide fix+checks, open PR to main, and confirm patch release.","bodyPreview":"# Hotfix Workflow\n\n本番障害向けのホットフィックスフローを開始し、`hotfix/*` ブランチ作成からパッチリリース確認までを案内する。\n\n## Preflight\n\n- `git status --short` が空であること\n- `main` ブランチが存在すること\n- `gh auth status` が成功すること\n\n## 実行内容\n\n1. 前提条件チェック\n2. `main` から `hotfix/*` ブランチ作成\n3. 修正・品質チェック・PR作成・リリース確認の手順提示\n\n## 使用方法\n\n### パターンA: Issue番号を指定\n\n```bash\n./scripts/release/create-hotfix.sh 42\n# -> hotfix/42\n```\n\n### パターンB: 説明を指定\n\n```bash\n./scripts/release/create-hotfix.sh fix-critical-bug\n# -> hotfix/fix-critical-bug\n```\n\n### パターンC: 対話式\n\n```bash\n./scripts","body":"# Hotfix Workflow\n\n本番障害向けのホットフィックスフローを開始し、`hotfix/*` ブランチ作成からパッチリリース確認までを案内する。\n\n## Preflight\n\n- `git status --short` が空であること\n- `main` ブランチが存在すること\n- `gh auth status` が成功すること\n\n## 実行内容\n\n1. 前提条件チェック\n2. `main` から `hotfix/*` ブランチ作成\n3. 修正・品質チェック・PR作成・リリース確認の手順提示\n\n## 使用方法\n\n### パターンA: Issue番号を指定\n\n```bash\n./scripts/release/create-hotfix.sh 42\n# -> hotfix/42\n```\n\n### パターンB: 説明を指定\n\n```bash\n./scripts/release/create-hotfix.sh fix-critical-bug\n# -> hotfix/fix-critical-bug\n```\n\n### パターンC: 対話式\n\n```bash\n./scripts/release/create-hotfix.sh\n```\n\n## 修正後の流れ\n\n```bash\n# 1) 修正実装\ngit add .\ngit commit -m \"fix: 緊急修正の説明\"\n\n# 2) 品質チェック\nmake quality-checks\n\n# 3) プッシュ + PR\ngit push -u origin hotfix/xxx\ngh pr create --base main --head hotfix/xxx \\\n  --title \"fix: 緊急修正の説明\" \\\n  --label \"hotfix,auto-merge\"\n\n# 4) リリース確認\ngh release view\n```\n\n## 注意\n\n- 緊急修正以外の変更を含めない\n- Conventional Commits で `fix:` プレフィックスを使う\n- main マージ後はパッチ版（例: v1.2.4）が自動作成される\n"},"lastSynced":"2026-02-28T12:52:51.154Z","agentAnalysis":{"suitability":{"en":"Perfect for Version Control Agents needing streamlined hotfix workflows with Git.","zh":"非常适合需要利用 Git 简化热修复工作流程的版本控制智能体。","ja":"Git を使用した合理化されたホットフィックスワークフローを必要とするバージョン管理エージェントに最適です。","ko":"Git을 사용하여 간소화된 핫픽스 워크플로우가 필요한 버전 관리 에이전트에 완벽합니다.","es":"Perfecto para Agentes de Control de Versiones que necesitan flujos de trabajo de hotfix optimizados con Git.","fr":"Parfait pour les Agents de Contrôle de Version ayant besoin de flux de travail de correctifs rationalisés avec Git.","de":"Perfekt für Version Control Agents, die optimierte Hotfix-Workflows mit Git benötigen.","pt":"Perfeito para Agentes de Controle de Versão que precisam de fluxos de trabalho de hotfix otimizados com Git.","ru":"Идеально подходит для агентов контроля версий, которым необходимы оптимизированные рабочие процессы hotfix с Git.","ar":"مثالي لعميليات التحكم في الإصدار التي تحتاج إلى تدفقات عمل حزم الإصلاح الساخنة المتدفقة مع Git."},"recommendation":{"en":"Empowers agents to automate hotfix workflows using Git, including load balancing and automatic model distribution, with features like `git status --short` checks and `gh auth status` validation, to efficiently manage and release patches.","zh":"赋能智能体使用 Git 自动化热修复工作流程，包括负载均衡和自动模型分发，并具有诸如 `git status --short` 检查和 `gh auth status` 验证等功能，以高效管理和发布补丁。","ja":"ロードバランシングや自動モデル配信を含む Git を使用したホットフィックスワークフローの自動化をエージェントに可能にし、`git status --short` チェックや `gh auth status` 検証などの機能により、パッチを効率的に管理およびリリースします。","ko":"로드 밸런싱 및 자동 모델 배포를 포함하여 Git을 사용하여 핫픽스 워크플로우를 자동화하고, `git status --short` 확인 및 `gh auth status` 검증과 같은 기능을 통해 패치를 효율적으로 관리 및 릴리스할 수 있도록 에이전트를 지원합니다.","es":"Permite a los agentes automatizar flujos de trabajo de hotfix utilizando Git, incluyendo balanceo de carga y distribución automática de modelos, con características como comprobaciones de `git status --short` y validación de `gh auth status`, para gestionar y liberar parches de manera eficiente.","fr":"Permet aux agents d''automatiser les flux de travail de correctifs à l''aide de Git, y compris l''équilibrage de charge et la distribution automatique de modèles, avec des fonctionnalités comme les vérifications `git status --short` et la validation `gh auth status`, pour gérer et publier efficacement des correctifs.","de":"Ermöglicht Agents, Hotfix-Workflows mit Git zu automatisieren, einschließlich Lastenausgleich und automatischer Modellverteilung, mit Funktionen wie `git status --short`-Prüfungen und `gh auth status`-Validierung, um Patches effizient zu verwalten und freizugeben.","pt":"Habilita os agentes a automatizar fluxos de trabalho de hotfix usando Git, incluindo balanceamento de carga e distribuição automática de modelos, com recursos como verificações `git status --short` e validação `gh auth status`, para gerenciar e liberar patches de forma eficiente.","ru":"Позволяет агентам автоматизировать рабочие процессы hotfix с помощью Git, включая балансировку нагрузки и автоматическое распределение моделей, с функциями, такими как проверки `git status --short` и валидация `gh auth status`, для эффективного управления и выпуска патчей.","ar":"يسمح للعميليات بتحسين تدفقات عمل حزم الإصلاح الساخنة باستخدام Git ، بما في ذلك موازنة الحمل وتوزيع النماذج التلقائي ، مع ميزات مثل عمليات فحص `git status --short` وعمليات التحقق `gh auth status` ، لإدارة وإصدار الرقع بكفاءة."},"useCases":{"en":["Automating hotfix branch creation","Streamlining patch release confirmation","Validating preflight conditions for hotfix workflows"],"zh":["自动化热修复分支创建","简化补丁发布确认","验证热修复工作流程的预检条件"],"ja":["ホットフィックスブランチ作成の自動化","パッチリリース確認の効率化","ホットフィックスワークフローの事前条件検証"],"ko":["핫픽스 브랜치 생성 자동화","패치 릴리스 확인 간소화","핫픽스 워크플로우에 대한 사전 조건 검증"],"es":["Automatización de la creación de ramas de hotfix","Optimización de la confirmación de liberación de parches","Validación de condiciones previas para flujos de trabajo de hotfix"],"fr":["Automatisation de la création de branches de correctifs","Rationalisation de la confirmation de publication des correctifs","Validation des conditions préalables pour les flux de travail de correctifs"],"de":["Automatisierung der Hotfix-Branch-Erstellung","Optimierung der Patch-Freigabebestätigung","Validierung von Preflight-Bedingungen für Hotfix-Workflows"],"pt":["Automação da criação de branch de hotfix","Otimização da confirmação de lançamento de patch","Validação de condições pré-voo para fluxos de trabalho de hotfix"],"ru":["Автоматизация создания ветки hotfix","Оптимизация подтверждения выпуска патча","Валидация предполётных условий для рабочих процессов hotfix"],"ar":["أتمتة إنشاء فرع حزم الإصلاح الساخنة","تحسين تأكيد إصدار الرقعة","التحقق من شروط ما قبل الطيران لتدفقات عمل حزم الإصلاح الساخنة"]},"limitations":{"en":["Requires Git installation","GitHub authentication needed","Limited to hotfix branch management"],"zh":["需要安装 Git","需要 GitHub 身份验证","仅限于热修复分支管理"],"ja":["Git のインストールが必要","GitHub 認証が必要","ホットフィックスブランチ管理に限定"],"ko":["Git 설치 필요","GitHub 인증 필요","핫픽스 브랜치 관리로 제한됨"],"es":["Requiere instalación de Git","Se necesita autenticación de GitHub","Limitado a la gestión de ramas de hotfix"],"fr":["Requiert l''installation de Git","Authentification GitHub nécessaire","Limité à la gestion des branches de correctifs"],"de":["Erfordert Git-Installation","GitHub-Authentifizierung erforderlich","Beschränkt auf die Verwaltung von Hotfix-Branches"],"pt":["Requer instalação do Git","Autenticação do GitHub necessária","Limitado ao gerenciamento de branch de hotfix"],"ru":["Требуется установка Git","Необходима аутентификация GitHub","Ограничен управлением веткой hotfix"],"ar":["يتطلب تثبيت Git","مطلوب مصادقة GitHub","محدود بإدارة فرع حزم الإصلاح الساخنة"]},"version":3},"contentHash":"17cc1b01e20874dbb0a36060132e269a2dd4fd5942479d6c82754edcba26ff86","qualityScore":25}');
